# More famous Welsh people, part E: more for every age, from the Red Lady of Paviland to today.
# Same format and house voice as people2a.py (EDITORIAL.md: proud, nothing negative about Welsh figures,
# tradition in its own words). Within an age, people keep this file's order when their dates tie.
from people2a import P

PEOPLE = [
 # ---------- Ancient Wales ----------
 P("red-lady-of-paviland", "ancient", "c. 31,000 BC", "The Red Lady of Paviland", "Dynes Goch Pafiland", "The oldest ceremonial burial in western Europe", "Y gladdedigaeth seremonïol hynaf yng ngorllewin Ewrop", "Red_Lady_of_Paviland", "heroes",
   "A young man laid to rest with red ochre, ivory and shells in a cave on Gower some 33,000 years ago: the oldest known ceremonial burial in western Europe.",
   "Gŵr ifanc a gladdwyd gydag ocr coch, ifori a chregyn mewn ogof ar Benrhyn Gŵyr tua 33,000 o flynyddoedd yn ôl: y gladdedigaeth seremonïol hynaf y gwyddys amdani yng ngorllewin Ewrop.",
   ["In 1823 the geologist William Buckland dug in Goat’s Hole at Paviland, high in the cliffs of Gower, and found a skeleton stained deep red. Beside it lay rods and rings of mammoth ivory and pierced shells. Buckland thought the bones were a woman’s, and the name the Red Lady stuck.",
    "Modern study shows he was a young man of about twenty-one, buried some 33,000 years ago, when Wales was a cold plain and the sea lay far away. Someone dressed him, coloured him with ochre and laid treasures with him. He is the oldest known ceremonial burial in western Europe, and the first named person in the long story of Wales."],
   ["Yn 1823 bu’r daearegwr William Buckland yn cloddio yn Nhwll yr Afr ym Mhafiland, yn uchel yng nghlogwyni Gŵyr, a chafodd sgerbwd wedi’i liwio’n goch tywyll. Wrth ei ochr roedd gwiail a modrwyau o ifori mamoth a chregyn wedi’u tyllu. Credai Buckland mai esgyrn menyw oedden nhw, a glynodd yr enw y Ddynes Goch.",
    "Mae astudiaeth fodern yn dangos mai gŵr ifanc tua un ar hugain oed oedd ef, a gladdwyd tua 33,000 o flynyddoedd yn ôl, pan oedd Cymru’n wastatir oer a’r môr ymhell i ffwrdd. Fe’i gwisgwyd, fe’i lliwiwyd ag ocr a gosodwyd trysorau gydag ef. Ef yw’r gladdedigaeth seremonïol hynaf y gwyddys amdani yng ngorllewin Ewrop, a’r person cyntaf yn stori hir Cymru."],
   first=("world", "The oldest known ceremonial burial in western Europe", "Y gladdedigaeth seremonïol hynaf y gwyddys amdani yng ngorllewin Ewrop", -31000)),
 P("caswallon", "ancient", "fl. 54 BC", "Cassivellaunus", "Caswallon fab Beli", "The king who faced Julius Caesar", "Y brenin a wynebodd Iŵl Cesar", "Cassivellaunus", "rulers",
   "The king chosen by the Britons to lead them against Julius Caesar’s invasion in 54 BC. Welsh tradition remembers him as Caswallon, son of Beli Mawr.",
   "Y brenin a ddewiswyd gan y Brythoniaid i’w harwain yn erbyn ymosodiad Iŵl Cesar yn 54 CC. Mae traddodiad Cymru’n ei gofio fel Caswallon fab Beli Mawr.",
   ["When Julius Caesar landed in Britain for the second time in 54 BC, the British peoples set aside their quarrels and gave the supreme command to Cassivellaunus. Caesar himself wrote his name down. Cassivellaunus fought him in open battle, then wore down his legions with chariots and sudden raids, and in the end Caesar sailed back to Gaul and did not return.",
    "Caesar called the people of the island Britons, and Welsh tradition kept their king’s memory. As Caswallon fab Beli he appears in the Welsh Triads and in the Mabinogion tale of Branwen, a king of the Island of Britain in the line of Beli Mawr, from whom the Welsh royal houses traced their descent."],
   ["Pan laniodd Iŵl Cesar ym Mhrydain am yr eildro yn 54 CC, rhoddodd pobloedd y Brythoniaid eu cwerylon o’r neilltu a rhoi’r prif awdurdod i Gaswallon. Cesar ei hun a gofnododd ei enw. Ymladdodd Caswallon ag ef ar faes agored, yna blinodd ei lengoedd â cherbydau rhyfel ac ymosodiadau sydyn, ac yn y diwedd hwyliodd Cesar yn ôl i Âl ac ni ddychwelodd.",
    "Brythoniaid oedd enw Cesar ar bobl yr ynys, a chadwodd traddodiad Cymru gof am eu brenin. Fel Caswallon fab Beli mae’n ymddangos yn y Trioedd ac yn chwedl Branwen yn y Mabinogion, brenin Ynys Prydain yn llinach Beli Mawr, yr olrheiniai tai brenhinol Cymru eu tras iddo."]),
 P("cynfelyn", "ancient", "d. c. AD 40", "Cunobelinus", "Cynfelyn", "King of the Britons", "Brenin y Brythoniaid", "Cunobelinus", "rulers",
   "The most powerful king in Britain before the Romans came, called King of the Britons by a Roman writer. He was the father of Caradog, and Welsh tradition remembers him as Cynfelyn.",
   "Y brenin mwyaf grymus ym Mhrydain cyn i’r Rhufeiniaid ddod, a alwyd yn Frenin y Brythoniaid gan awdur Rhufeinig. Ef oedd tad Caradog, ac mae traddodiad Cymru’n ei gofio fel Cynfelyn.",
   ["For some thirty years Cunobelinus ruled much of southern Britain from his capital at Camulodunum. His gold coins, stamped with an ear of barley and a horse, have been found across the south, and the Roman writer Suetonius called him simply ‘King of the Britons’.",
    "His sons Caradog and Togodumnus led the fight when Rome invaded in AD 43. Welsh tradition remembered the father as Cynfelyn, and his name passed down in Welsh pedigrees. Shakespeare made him the hero of his play Cymbeline."],
   ["Am ryw ddeng mlynedd ar hugain rheolodd Cynfelyn ran helaeth o dde Prydain o’i brifddinas yn Camulodunum. Cafwyd ei ddarnau arian aur, â thywysen haidd a cheffyl arnynt, ar draws y de, a galwodd yr awdur Rhufeinig Suetonius ef yn syml yn ‘Frenin y Brythoniaid’.",
    "Ei feibion Caradog a Togodumnus a arweiniodd y frwydr pan ymosododd Rhufain yn 43 OC. Cofiodd traddodiad Cymru’r tad fel Cynfelyn, a throsglwyddwyd ei enw yn achau Cymru. Gwnaeth Shakespeare ef yn arwr ei ddrama Cymbeline."]),

 # ---------- Roman Wales ----------
 P("buddug", "roman", "d. AD 61", "Boudica", "Buddug", "Queen who rose against Rome", "Brenhines a gododd yn erbyn Rhufain", "Boudica", "heroes",
   "Queen of the Iceni who led the great British rising against Rome in AD 60–61, while the Roman army was attacking the druids of Anglesey. Her statue stands among the Heroes of Wales in Cardiff City Hall.",
   "Brenhines yr Iceni a arweiniodd wrthryfel mawr y Brythoniaid yn erbyn Rhufain yn 60–61 OC, tra oedd y fyddin Rufeinig yn ymosod ar dderwyddon Môn. Saif ei cherflun ymhlith Arwyr Cymru yn Neuadd y Ddinas, Caerdydd.",
   ["In AD 60 the Roman governor Suetonius Paulinus marched his army to the Menai Strait to destroy the druids on Anglesey, the holy island of the Britons. Behind his back, Boudica, queen of the Iceni, raised the peoples of the east in revenge for the wrongs done to her and her daughters.",
    "Her army swept through Camulodunum, Londinium and Verulamium and came close to driving Rome out of Britain. The Welsh have always counted her one of their own, as Buddug, a Briton who stood up for her people. When the Heroes of Wales were carved in marble for Cardiff City Hall in 1916, she was among them."],
   ["Yn 60 OC gorymdeithiodd y llywodraethwr Rhufeinig Suetonius Paulinus â’i fyddin at y Fenai i ddinistrio’r derwyddon ar Ynys Môn, ynys sanctaidd y Brythoniaid. Y tu ôl i’w gefn, cododd Buddug, brenhines yr Iceni, bobloedd y dwyrain i ddial y camweddau a wnaed iddi hi a’i merched.",
    "Ysgubodd ei byddin drwy Camulodunum, Londinium a Verulamium a bu bron iddi yrru Rhufain o Brydain. Mae’r Cymry erioed wedi’i chyfrif yn un ohonyn nhw, fel Buddug, Brythones a safodd dros ei phobl. Pan gerfiwyd Arwyr Cymru mewn marmor ar gyfer Neuadd y Ddinas Caerdydd yn 1916, roedd hi yn eu plith."]),
 P("julius-and-aaron", "roman", "d. c. 304", "Julius and Aaron", "Iŵl ac Aaron", "Martyrs of Caerleon", "Merthyron Caerllion", "Julius_and_Aaron", "faith",
   "Two Christians of the Roman city of Caerleon who died for their faith around 304. They are the first known Christian martyrs of Wales.",
   "Dau Gristion o ddinas Rufeinig Caerllion a fu farw dros eu ffydd tua 304. Hwy yw’r merthyron Cristnogol cyntaf y gwyddys amdanynt yng Nghymru.",
   ["Julius and Aaron lived at Caerleon, the great fortress of the Second Augustan Legion, when Christians across the empire were being hunted. Gildas, writing in the sixth century, names them with Saint Alban as the martyrs of Britain who would not give up their faith.",
    "Churches were raised in their memory at Caerleon, and the Book of Llandaf records land there given to them. Their names are among the very first of any Christians in Wales."],
   ["Roedd Iŵl ac Aaron yn byw yng Nghaerllion, caer fawr yr Ail Leng Awgwstaidd, pan oedd Cristnogion ar draws yr ymerodraeth yn cael eu herlid. Mae Gildas, yn ysgrifennu yn y chweched ganrif, yn eu henwi gyda Sant Alban fel merthyron Prydain na fynnent ildio’u ffydd.",
    "Codwyd eglwysi er cof amdanynt yng Nghaerllion, ac mae Llyfr Llandaf yn cofnodi tir yno a roddwyd iddynt. Mae eu henwau ymhlith y cyntaf un o unrhyw Gristnogion yng Nghymru."],
   first=("wales", "The first known Christian martyrs of Wales", "Y merthyron Cristnogol cyntaf y gwyddys amdanynt yng Nghymru", 304)),
 P("coel-hen", "roman", "fl. c. 400", "Coel Hen", "Coel Hen", "Forefather of the Old North", "Cyndad yr Hen Ogledd", "Coel_Hen", "rulers",
   "A British king of the north at the end of Roman rule. Welsh tradition holds him to be the forefather of Urien Rheged and many kings of the Old North, and the Old King Cole of the rhyme.",
   "Brenin Brythonig yn y gogledd ar ddiwedd oes Rhufain. Yn ôl traddodiad Cymru ef oedd cyndad Urien Rheged a llawer o frenhinoedd yr Hen Ogledd, a’r Old King Cole yn yr hwiangerdd.",
   ["As the legions left Britain, the Britons of the north looked to their own leaders. The old Welsh pedigrees place Coel Hen, Coel the Old, at the head of the great family of northern kings, the Coeling.",
    "From him, Welsh tradition holds, came Urien of Rheged, whom Taliesin praised, and Gwallog, Llywarch Hen and the other heroes of the Old North, whose Welsh-speaking kingdoms stretched from the Pennines to the Clyde. He lives on in English as Old King Cole."],
   ["Wrth i’r llengoedd adael Prydain, troes Brythoniaid y gogledd at eu harweinwyr eu hunain. Mae’r hen achau Cymreig yn gosod Coel Hen ar ben teulu mawr brenhinoedd y gogledd, y Coeling.",
    "Ohono ef, yn ôl traddodiad Cymru, y daeth Urien Rheged, a folwyd gan Daliesin, a Gwallog, Llywarch Hen ac arwyr eraill yr Hen Ogledd, y mae eu teyrnasoedd Cymraeg yn ymestyn o fryniau’r Pennines hyd afon Clud. Mae’n fyw o hyd yn Saesneg fel Old King Cole."]),

 # ---------- The Age of Saints ----------
 P("brychan", "saints", "fl. 5th century", "Brychan Brycheiniog", "Brychan Brycheiniog", "King and father of saints", "Brenin a thad saint", "Brychan", "rulers",
   "The king who gave his name to Brycheiniog, Brecknock. Welsh tradition holds that he had two dozen children, and that most of them became saints.",
   "Y brenin a roddodd ei enw i Frycheiniog. Yn ôl traddodiad Cymru roedd ganddo ddau ddwsin o blant, a daeth y rhan fwyaf ohonynt yn saint.",
   ["Brychan ruled the land around the upper Usk in the fifth century. It was called Garthmadrun before him, and it has carried his name ever since: Brycheiniog, the kingdom of Brychan, Brecknock in English, and today the Bannau Brycheiniog.",
    "## His birth",
    "Two old Latin texts tell his story, De Situ Brecheniauc and Cognatio de Brychan, kept at Brecon and copied in the Middle Ages from older writings. His mother Marchell was the daughter of Tewdrig, king of Garthmadrun. She crossed the sea to Ireland in the depth of winter and married Anlach, son of an Irish king, and their son Brychan was born there. Anlach brought his wife and son home to Garthmadrun, and in time Brychan ruled his mother’s land, so that the house of Brycheiniog joined the Britons of Wales with the royal blood of Ireland.",
    "## Father of saints",
    "No family in the Age of Saints is greater. The Triads name the Three Saintly Lineages of the Island of Britain: the line of Brychan Brycheiniog, the line of Cunedda Wledig and the line of Caw of Prydyn. Gerald of Wales, riding through Brycheiniog in 1188, wrote that Brychan had twenty-four daughters, all given to God from their youth, who lived holy lives and died blessed.",
    "|| Cynog | his eldest son, martyr, of Merthyr Cynog; Gerald saw the torque Brychan gave him",
    "|| Gwladys | wife of King Gwynllyw and mother of Saint Cadog",
    "|| Dwynwen | the saint of lovers, of Llanddwyn in Ynys Môn",
    "|| Tudful | whose name lives on in Merthyr Tudful",
    "|| Tybie | of Llandybie",
    "|| Elined | of Slwch near Brecon, whose feast Gerald saw kept with song and dance",
    "|| Ceinwen | of Llangeinwen and Cerrigceinwen in Ynys Môn",
    "|| Cain | of Llangeinor, and of St Keyne in Cornwall",
    "|| Nefyn | mother, in the Welsh pedigrees, of Urien, king of Rheged",
    "Churches across Wales, Cornwall, Devon and Brittany bear the names of Brychan’s children, and the Cornish tell their own list of them, with Saint Nectan of Hartland at its head.",
    "## Brychan and Arthur",
    "Brychan’s family runs right through Arthur’s story. The Life of Saint Cadog tells how Gwynllyw, king of Gwynllŵg, carried away Brychan’s daughter Gwladys, and how Brychan rode after them with his army, until Arthur, Cai and Bedwyr came down from the hill to stand by Gwynllyw. So Brychan became the grandfather of Cadog, the saint of Llancarfan. And through his daughter Nefyn, the Welsh pedigrees make him the grandfather of Urien Rheged and the great-grandfather of Owain ab Urien, the knight of the fountain.",
    "His sons ruled after him, and the kings of Brycheiniog were of his line for four hundred years. Around 890 they built a royal hall on an island in Llyn Syfaddan, Llangors Lake, the only crannog in Wales. Brychan himself stands today in the stained glass of Brecon Cathedral, at the heart of the land that bears his name."],
   ["Rheolai Brychan y wlad o gwmpas blaenau Wysg yn y bumed ganrif. Garthmadrun oedd ei henw cyn ei amser ef, ac mae wedi dwyn ei enw ef byth ers hynny: Brycheiniog, teyrnas Brychan, a Bannau Brycheiniog heddiw.",
    "## Ei eni",
    "Mae dau hen destun Lladin yn adrodd ei hanes, De Situ Brecheniauc a Cognatio de Brychan, a gedwid yn Aberhonddu ac a gopïwyd yn yr Oesoedd Canol o ysgrifau hŷn. Ei fam Marchell oedd merch Tewdrig, brenin Garthmadrun. Croesodd y môr i Iwerddon yng nghanol gaeaf a phriodi Anlach, mab brenin Gwyddelig, ac yno y ganed eu mab Brychan. Dygodd Anlach ei wraig a’i fab adref i Garthmadrun, ac ymhen amser rheolodd Brychan wlad ei fam, fel bod tŷ Brycheiniog yn uno Brythoniaid Cymru â gwaed brenhinol Iwerddon.",
    "## Tad y saint",
    "Nid oes teulu mwy yn Oes y Saint. Mae’r Trioedd yn enwi Tair Gwelygordd Saint Ynys Prydain: llinach Brychan Brycheiniog, llinach Cunedda Wledig a llinach Caw o Brydyn. Ysgrifennodd Gerallt Gymro, wrth farchogaeth drwy Frycheiniog yn 1188, fod gan Frychan bedair merch ar hugain, pob un wedi’i rhoi i Dduw o’i hieuenctid, a fu fyw’n sanctaidd ac a fu farw’n fendigaid.",
    "|| Cynog | ei fab hynaf, merthyr, o Ferthyr Cynog; gwelodd Gerallt y dorch a roddodd Brychan iddo",
    "|| Gwladys | gwraig y Brenin Gwynllyw a mam Cadog Sant",
    "|| Dwynwen | santes y cariadon, o Landdwyn ym Môn",
    "|| Tudful | y mae ei henw’n fyw ym Merthyr Tudful",
    "|| Tybie | o Landybïe",
    "|| Elined | o’r Slwch ger Aberhonddu, y gwelodd Gerallt gadw ei gŵyl â chân a dawns",
    "|| Ceinwen | o Langeinwen a Cherrigceinwen ym Môn",
    "|| Cain | o Langeinwyr, ac o St Keyne yng Nghernyw",
    "|| Nefyn | mam Urien, brenin Rheged, yn ôl yr achau Cymreig",
    "Mae eglwysi ledled Cymru, Cernyw, Dyfnaint a Llydaw yn dwyn enwau plant Brychan, ac mae gan y Cernywiaid eu rhestr eu hunain ohonynt, â Sant Nectan o Hartland ar ei phen.",
    "## Brychan ac Arthur",
    "Mae teulu Brychan yn rhedeg drwy hanes Arthur. Mae Buchedd Cadog Sant yn adrodd sut y cipiodd Gwynllyw, brenin Gwynllŵg, Wladys ferch Brychan, a sut y marchogodd Brychan ar eu hôl â’i fyddin, nes i Arthur, Cai a Bedwyr ddod i lawr o’r bryn i sefyll gyda Gwynllyw. Felly daeth Brychan yn daid i Gadog, sant Llancarfan. A thrwy ei ferch Nefyn, mae’r achau Cymreig yn ei wneud yn daid i Urien Rheged ac yn hen daid i Owain ab Urien, marchog y ffynnon.",
    "Teyrnasodd ei feibion ar ei ôl, ac roedd brenhinoedd Brycheiniog o’i linach ef am bedwar can mlynedd. Tua 890 codasant neuadd frenhinol ar ynys yn Llyn Syfaddan, yr unig grannog yng Nghymru. Saif Brychan ei hun heddiw yng ngwydr lliw Eglwys Gadeiriol Aberhonddu, yng nghanol y wlad sy’n dwyn ei enw."]),
 P("dwynwen", "saints", "fl. 5th century", "Saint Dwynwen", "Santes Dwynwen", "Patron saint of lovers", "Nawddsantes cariadon", "Saint_Dwynwen", "faith",
   "Daughter of Brychan and the Welsh saint of lovers. Her day, 25 January, is Wales’s own day for sweethearts, and her church stands on Llanddwyn Island in Anglesey.",
   "Merch Brychan a santes cariadon Cymru. Ei dydd hi, 25 Ionawr, yw diwrnod cariadon Cymru, ac mae ei heglwys ar Ynys Llanddwyn ym Môn.",
   ["Welsh tradition tells that Dwynwen loved a young man named Maelon but could not marry him. She prayed to be free of her sorrow, and was granted three wishes: that Maelon be healed, that God would look after all true lovers, and that she would never wish to marry.",
    "She gave her life to God on Llanddwyn, a little tidal island off Anglesey, where the ruins of her church and a holy well still draw visitors. Every 25 January, Dydd Santes Dwynwen, people across Wales send cards and gifts to the ones they love."],
   ["Mae traddodiad Cymru’n adrodd i Ddwynwen garu llanc o’r enw Maelon ond na allai ei briodi. Gweddïodd am gael ei rhyddhau o’i gofid, a chafodd dri dymuniad: i Faelon gael ei iacháu, i Dduw ofalu am bob gwir gariad, ac na fyddai hi byth eisiau priodi.",
    "Rhoddodd ei bywyd i Dduw ar Landdwyn, ynys fach lanw ger Môn, lle mae adfeilion ei heglwys a ffynnon sanctaidd yn dal i ddenu ymwelwyr. Bob 25 Ionawr, ar Ddydd Santes Dwynwen, mae pobl ledled Cymru’n anfon cardiau ac anrhegion at y rhai a garant."]),
 P("patrick", "saints", "fl. 5th century", "Saint Patrick", "Padrig Sant", "Briton who became apostle of Ireland", "Brython a ddaeth yn apostol Iwerddon", "Saint_Patrick", "faith",
   "A Briton, taken as a boy by Irish raiders, who escaped and went back as a bishop to bring Christianity to Ireland. Welsh tradition holds that he was born in Wales.",
   "Brython a gipiwyd yn fachgen gan ysbeilwyr o Iwerddon, a ddihangodd ac a aeth yn ôl yn esgob i ddod â Christnogaeth i Iwerddon. Yn ôl traddodiad Cymru fe’i ganed yng Nghymru.",
   ["In his own words, the Confessio, Patrick tells how he was the son of a deacon, Calpurnius, at a place called Bannavem Taburniae in Britain, and how he was seized at sixteen and taken as a slave to Ireland. After six years he escaped and came home.",
    "A dream called him back. He returned as a bishop and spent the rest of his life teaching the Irish, who honour him as their patron saint. His writings are among the earliest by any Briton, and Welsh tradition holds that his birthplace was in Wales, with Banwen in the Dulais valley among the places that claim him."],
   ["Yn ei eiriau ei hun, y Confessio, mae Padrig yn adrodd mai mab diacon, Calpurnius, ydoedd, mewn lle o’r enw Bannavem Taburniae ym Mhrydain, a sut y cipiwyd ef yn un ar bymtheg a’i gludo’n gaethwas i Iwerddon. Ar ôl chwe blynedd dihangodd a dod adref.",
    "Galwodd breuddwyd ef yn ôl. Dychwelodd yn esgob a threuliodd weddill ei oes yn dysgu’r Gwyddelod, sy’n ei anrhydeddu fel eu nawddsant. Mae ei ysgrifeniadau ymhlith y cynharaf gan unrhyw Frython, ac yn ôl traddodiad Cymru roedd ei fan geni yng Nghymru, a Banwen yng nghwm Dulais ymhlith y mannau sy’n ei hawlio."]),
 P("non", "saints", "fl. 6th century", "Saint Non", "Santes Non", "Mother of Saint David", "Mam Dewi Sant", "Saint_Non", "faith",
   "The mother of Dewi Sant, patron saint of Wales. Her chapel and holy well stand on the cliffs near St Davids, where Welsh tradition holds that David was born in a storm.",
   "Mam Dewi Sant, nawddsant Cymru. Saif ei chapel a’i ffynnon sanctaidd ar y clogwyni ger Tyddewi, lle y ganed Dewi mewn storm yn ôl traddodiad Cymru.",
   ["Welsh tradition tells that Non gave birth to David on a clifftop above St Non’s Bay during a wild storm, and that a calm light shone over the place while the storm raged all around. A spring burst from the ground there, and St Non’s Well has drawn pilgrims ever since.",
    "Non later went to Cornwall and Brittany, where churches also bear her name, and Welsh tradition holds that her tomb is at Dirinon in Brittany. Her ruined chapel near St Davids is one of the oldest Christian sites in Wales."],
   ["Mae traddodiad Cymru’n adrodd i Non eni Dewi ar ben clogwyn uwchben Bae Santes Non yn ystod storm wyllt, ac i olau tawel dywynnu dros y fan tra oedd y storm yn rhuo o gwmpas. Tarddodd ffynnon o’r ddaear yno, ac mae Ffynnon Non wedi denu pererinion byth ers hynny.",
    "Aeth Non wedyn i Gernyw a Llydaw, lle mae eglwysi hefyd yn dwyn ei henw, ac yn ôl traddodiad Cymru mae ei bedd yn Dirinon yn Llydaw. Mae adfail ei chapel ger Tyddewi yn un o’r safleoedd Cristnogol hynaf yng Nghymru."]),
 P("samson", "saints", "c. 485–c. 565", "Saint Samson", "Sant Samson", "Welsh founder of Dol in Brittany", "Sefydlydd Dol yn Llydaw", "Samson_of_Dol", "faith",
   "A pupil of Illtud at Llanilltud Fawr who became abbot of Caldey, then sailed to Cornwall and Brittany and founded the great monastery of Dol. His Life is the oldest life of any British saint.",
   "Disgybl i Illtud yn Llanilltud Fawr a ddaeth yn abad Ynys Bŷr, yna a hwyliodd i Gernyw a Llydaw a sefydlu mynachlog fawr Dol. Ei Fuchedd ef yw’r fuchedd hynaf o unrhyw sant Brythonig.",
   ["Samson was born in south Wales and given as a boy to Illtud’s school at Llanilltud Fawr, where he became famous for his learning and his discipline. He went on to lead the monks on Ynys Bŷr, Caldey Island.",
    "He sailed to Cornwall and then to Brittany, where he founded the monastery of Dol, and in 557 he signed the acts of a church council in Paris as a bishop. His Life, written perhaps a century or two after his death, is the oldest life of any saint of Britain, and Dol honoured him as one of the seven founder saints of Brittany."],
   ["Ganed Samson yn ne Cymru a’i roi’n fachgen i ysgol Illtud yn Llanilltud Fawr, lle daeth yn enwog am ei ddysg a’i ddisgyblaeth. Aeth ymlaen i arwain y mynaich ar Ynys Bŷr.",
    "Hwyliodd i Gernyw ac yna i Lydaw, lle sefydlodd fynachlog Dol, ac yn 557 llofnododd weithredoedd cyngor eglwysig ym Mharis fel esgob. Ei Fuchedd ef, a ysgrifennwyd efallai ganrif neu ddwy wedi ei farw, yw’r fuchedd hynaf o unrhyw sant o Brydain, ac anrhydeddodd Dol ef fel un o saith sant sefydlu Llydaw."]),
 P("teilo", "saints", "fl. 6th century", "Saint Teilo", "Teilo Sant", "Founder of Llandeilo", "Sefydlydd Llandeilo", "Saint_Teilo", "faith",
   "A friend of Dewi Sant who founded the church at Llandeilo Fawr. In the margins of the gospel book kept at his church is the oldest written Welsh prose to survive.",
   "Cyfaill i Ddewi Sant a sefydlodd yr eglwys yn Llandeilo Fawr. Ar ymyl tudalennau llyfr efengylau a gadwyd yn ei eglwys y mae’r rhyddiaith Gymraeg ysgrifenedig hynaf sydd wedi goroesi.",
   ["Teilo was born near Penally in Pembrokeshire and studied with Dewi Sant, travelling with him, Welsh tradition holds, to Jerusalem. He founded a great church at Llandeilo Fawr on the Tywi, and more than twenty churches in south Wales bear his name.",
    "In the eighth and ninth centuries a beautiful gospel book, now called the Lichfield Gospels, lay on the altar of Teilo’s church. In its margins someone wrote down a land agreement in Welsh, the Surexit memorandum. It is the oldest written Welsh prose that survives. Welsh tradition holds that Teilo’s body was so loved that three churches, Llandeilo, Llandaf and Penally, each received it."],
   ["Ganed Teilo ger Penalun yn Sir Benfro ac astudiodd gyda Dewi Sant, gan deithio gydag ef, yn ôl traddodiad Cymru, i Gaersalem. Sefydlodd eglwys fawr yn Llandeilo Fawr ar lan Tywi, ac mae dros ugain o eglwysi yn ne Cymru yn dwyn ei enw.",
    "Yn yr wythfed a’r nawfed ganrif gorweddai llyfr efengylau hardd, a elwir heddiw yn Efengylau Caerlwytgoed, ar allor eglwys Teilo. Yn ei ymylon ysgrifennodd rhywun gytundeb tir yn Gymraeg, memorandwm Surexit. Dyma’r rhyddiaith Gymraeg ysgrifenedig hynaf sydd wedi goroesi. Yn ôl traddodiad Cymru roedd corff Teilo mor annwyl nes i dair eglwys, Llandeilo, Llandaf a Phenalun, ei dderbyn bob un."],
   first=("wales", "The oldest written Welsh prose that survives, in the gospel book at his church", "Y rhyddiaith Gymraeg ysgrifenedig hynaf sydd wedi goroesi, yn llyfr efengylau ei eglwys", 800)),
 P("padarn", "saints", "fl. 6th century", "Saint Padarn", "Padarn Sant", "Founder of Llanbadarn Fawr", "Sefydlydd Llanbadarn Fawr", "Saint_Paternus", "faith",
   "The saint who founded the monastery and bishopric of Llanbadarn Fawr, near Aberystwyth, which became one of the great centres of learning in Wales.",
   "Y sant a sefydlodd fynachlog ac esgobaeth Llanbadarn Fawr, ger Aberystwyth, a ddaeth yn un o ganolfannau dysg mawr Cymru.",
   ["Welsh tradition holds that Padarn came from Brittany with a band of monks and settled by the Rheidol, where he founded Llanbadarn Fawr. He is named with Dewi and Teilo as one of the three blessed visitors of the Island of Britain.",
    "His monastery grew into a famous school. In the eleventh century Sulien and his sons copied and wrote books there, and the great church that stands at Llanbadarn today was raised on Padarn’s ground. Llanbadarn is also where Dafydd ap Gwilym went to church and wrote about the girls he watched there."],
   ["Yn ôl traddodiad Cymru daeth Padarn o Lydaw gyda mintai o fynaich ac ymsefydlu ger afon Rheidol, lle sefydlodd Lanbadarn Fawr. Fe’i henwir gyda Dewi a Theilo fel un o dri gwestai gwynfydedig Ynys Prydain.",
    "Tyfodd ei fynachlog yn ysgol enwog. Yn yr unfed ganrif ar ddeg bu Sulien a’i feibion yn copïo ac yn ysgrifennu llyfrau yno, ac ar dir Padarn y codwyd yr eglwys fawr sy’n sefyll yn Llanbadarn heddiw. Yn Llanbadarn hefyd yr âi Dafydd ap Gwilym i’r eglwys ac yr ysgrifennodd am y merched a welai yno."]),
 P("deiniol", "saints", "d. c. 584", "Saint Deiniol", "Deiniol Sant", "Founder of Bangor", "Sefydlydd Bangor", "Deiniol", "faith",
   "The founder of the monastery at Bangor around 525 and its first bishop. Bangor is one of the oldest bishoprics in Britain.",
   "Sefydlydd y fynachlog ym Mangor tua 525 a’i hesgob cyntaf. Mae Bangor yn un o’r esgobaethau hynaf ym Mhrydain.",
   ["Deiniol built his monastery inside a wattle fence, a bangor in Welsh, on the shore of the Menai, and the city has kept the name. Welsh tradition holds that Maelgwn Gwynedd gave him the land and made him the first bishop of Gwynedd.",
    "Bangor Cathedral stands on the place he chose, and its bishopric is among the oldest in Britain. He is also remembered at Hawarden, where Gladstone’s great library, St Deiniol’s, was named after him."],
   ["Cododd Deiniol ei fynachlog o fewn ffens o wiail, bangor yn Gymraeg, ar lan y Fenai, ac mae’r ddinas wedi cadw’r enw. Yn ôl traddodiad Cymru, Maelgwn Gwynedd a roddodd y tir iddo a’i wneud yn esgob cyntaf Gwynedd.",
    "Saif Eglwys Gadeiriol Bangor ar y llecyn a ddewisodd, ac mae ei hesgobaeth ymhlith yr hynaf ym Mhrydain. Fe’i cofir hefyd ym Mhenarlâg, lle enwyd llyfrgell fawr Gladstone, Llyfrgell Sant Deiniol, ar ei ôl."]),
 P("cybi", "saints", "fl. 6th century", "Saint Cybi", "Cybi Sant", "Founder of Holyhead", "Sefydlydd Caergybi", "Saint_Cybi", "faith",
   "The Cornish-born saint who built his church inside the Roman fort at Holyhead, which in Welsh still bears his name: Caergybi.",
   "Y sant o Gernyw a gododd ei eglwys o fewn y gaer Rufeinig yng Nghaergybi, sy’n dal i ddwyn ei enw.",
   ["Cybi was given the old Roman fort at the tip of Holy Island by Maelgwn Gwynedd, and set his church within its walls. St Cybi’s Church still stands there, inside walls that the Romans built.",
    "Welsh tradition tells of his friendship with Seiriol of Penmon. The two met each week at the wells of Clorach in the middle of Anglesey. Cybi walked there facing the sun both ways and grew brown, while Seiriol walked with the sun behind him and stayed pale, so they were called Cybi Felyn and Seiriol Wyn."],
   ["Rhoddodd Maelgwn Gwynedd yr hen gaer Rufeinig ar flaen Ynys Gybi i Gybi, a gosododd yntau ei eglwys o fewn ei muriau. Mae Eglwys Sant Cybi yn sefyll yno o hyd, o fewn muriau a gododd y Rhufeiniaid.",
    "Mae traddodiad Cymru’n adrodd am ei gyfeillgarwch â Seiriol o Benmon. Cyfarfyddai’r ddau bob wythnos wrth ffynhonnau Clorach yng nghanol Môn. Cerddai Cybi yno gan wynebu’r haul bob ffordd a llosgai’n felyn, tra cerddai Seiriol â’r haul y tu ôl iddo ac arhosai’n welw, felly fe’u galwyd yn Gybi Felyn a Seiriol Wyn."]),
 P("melangell", "saints", "fl. 7th century", "Saint Melangell", "Santes Melangell", "Protector of hares", "Nawddsantes yr ysgyfarnogod", "Saint_Melangell", "faith",
   "The saint who sheltered a hunted hare under her cloak. The king of Powys gave her the valley of Pennant Melangell, where her twelfth-century shrine still stands.",
   "Y santes a gysgododd ysgyfarnog dan ei mantell. Rhoddodd brenin Powys gwm Pennant Melangell iddi, lle saif ei chysegrfa o’r ddeuddegfed ganrif o hyd.",
   ["Welsh tradition tells that Brochwel Ysgithrog, king of Powys, was hunting in the Berwyn hills when his hounds chased a hare into a thicket. There he found Melangell at prayer, with the hare hiding beneath her robe, and the hounds fled and would not come near.",
    "Moved by her holiness, the king gave her the valley as a place of sanctuary. Her church at Pennant Melangell holds her rebuilt Romanesque shrine of the twelfth century, one of the oldest in northern Europe, and hares there were called Melangell’s lambs."],
   ["Mae traddodiad Cymru’n adrodd bod Brochwel Ysgithrog, brenin Powys, yn hela ym mryniau’r Berwyn pan erlidiodd ei gŵn ysgyfarnog i ddrysni. Yno cafodd Melangell yn gweddïo, a’r ysgyfarnog yn cuddio dan ei gwisg, a ffodd y cŵn heb fentro’n agos.",
    "Wedi’i gyffwrdd gan ei sancteiddrwydd, rhoddodd y brenin y cwm iddi yn noddfa. Yn ei heglwys ym Mhennant Melangell mae ei chysegrfa Romanésg o’r ddeuddegfed ganrif, wedi’i hailgodi, un o’r hynaf yng ngogledd Ewrop, a gelwid ysgyfarnogod y fro yn ŵyn Melangell."]),
 P("beuno", "saints", "d. c. 640", "Saint Beuno", "Beuno Sant", "Founder of Clynnog Fawr", "Sefydlydd Clynnog Fawr", "Saint_Beuno", "faith",
   "The saint of Clynnog Fawr in Llŷn, whose church became a great stop on the pilgrims’ road to Bardsey. Welsh tradition holds that he raised his niece Gwenfrewi to life.",
   "Sant Clynnog Fawr yn Llŷn, y daeth ei eglwys yn arhosfan fawr ar ffordd y pererinion i Enlli. Yn ôl traddodiad Cymru adferodd ei nith Gwenfrewi yn fyw.",
   ["Beuno was born in Powys and founded churches across north Wales before settling at Clynnog Fawr, on the north coast of Llŷn. The grand church there, rebuilt around 1500, still has his chapel and his well.",
    "Pilgrims on their way to Bardsey stopped at Clynnog to pray at Beuno’s tomb. Welsh tradition tells that at Holywell he restored his niece, Gwenfrewi, to life, and that a spring rose where she had fallen. The Jesuit college of St Beuno’s, where the poet Gerard Manley Hopkins learned Welsh, carries his name."],
   ["Ganed Beuno ym Mhowys a sefydlodd eglwysi ar draws gogledd Cymru cyn ymsefydlu yng Nghlynnog Fawr, ar arfordir gogleddol Llŷn. Mae gan yr eglwys fawreddog yno, a ailgodwyd tua 1500, ei gapel a’i ffynnon o hyd.",
    "Arhosai pererinion ar eu ffordd i Enlli yng Nghlynnog i weddïo wrth fedd Beuno. Mae traddodiad Cymru’n adrodd iddo adfer ei nith, Gwenfrewi, yn fyw yn Nhreffynnon, ac i ffynnon darddu lle y syrthiodd. Mae coleg yr Iesuwyr, Sant Beuno, lle dysgodd y bardd Gerard Manley Hopkins Gymraeg, yn dwyn ei enw."]),
 P("gwenfrewi", "saints", "fl. 7th century", "Saint Winefride", "Santes Gwenfrewi", "Saint of Holywell", "Santes Treffynnon", "Saint_Winefride", "faith",
   "The saint of Holywell, whose well has drawn pilgrims for some thirteen hundred years. It is one of the Seven Wonders of Wales.",
   "Santes Treffynnon, y mae ei ffynnon wedi denu pererinion ers tua thair canrif ar ddeg. Mae’n un o Saith Rhyfeddod Cymru.",
   ["Welsh tradition tells that Gwenfrewi, a young woman of Tegeingl, was attacked by a prince named Caradog because she chose to give her life to God. Where she fell a spring burst from the ground, and her uncle Beuno restored her to life. She became abbess of Gwytherin, where she died.",
    "Her well at Holywell, Treffynnon, became the most famous holy well in Britain. Kings and commoners came to bathe in its waters, and the beautiful well chapel was built over the spring around 1500 by Lady Margaret Beaufort, mother of Henry Tudor. Pilgrims still come, and it is counted among the Seven Wonders of Wales."],
   ["Mae traddodiad Cymru’n adrodd i Wenfrewi, merch ifanc o Degeingl, gael ei hymosod gan dywysog o’r enw Caradog am iddi ddewis rhoi ei bywyd i Dduw. Lle y syrthiodd tarddodd ffynnon o’r ddaear, ac adferodd ei hewythr Beuno hi’n fyw. Daeth yn abades Gwytherin, lle bu farw.",
    "Daeth ei ffynnon yn Nhreffynnon yn ffynnon sanctaidd enwocaf Prydain. Deuai brenhinoedd a gwerin i ymdrochi yn ei dyfroedd, a chodwyd capel hardd y ffynnon dros y tarddiad tua 1500 gan yr Arglwyddes Margaret Beaufort, mam Harri Tudur. Daw pererinion o hyd, ac fe’i cyfrifir ymhlith Saith Rhyfeddod Cymru."]),

 # ---------- The Age of Kings ----------
 P("elisedd", "kings", "fl. 8th century", "Elisedd ap Gwylog", "Elisedd ap Gwylog", "King who won back Powys", "Y brenin a adenillodd Bowys", "Elisedd_ap_Gwylog", "rulers",
   "King of Powys who won back his land from the English by the sword. His great-grandson raised the Pillar of Eliseg in his honour near Llangollen.",
   "Brenin Powys a adenillodd ei dir oddi ar y Saeson â’r cleddyf. Cododd ei orwyr Biler Eliseg er anrhydedd iddo ger Llangollen.",
   ["In the eighth century the kingdom of Powys was hard pressed by Mercia. Elisedd ap Gwylog fought back, and the words carved on his memorial say that he took the inheritance of Powys out of the power of the English, with fire and with his sword.",
    "The Pillar of Eliseg still stands on its mound near Valle Crucis Abbey. Its long Latin inscription, now worn away but copied in 1696 by Edward Lhuyd, traced the line of Powys back to Macsen Wledig and Gwrtheyrn, and is one of the most precious early records of Wales."],
   ["Yn yr wythfed ganrif roedd teyrnas Powys dan bwysau trwm gan Mersia. Ymladdodd Elisedd ap Gwylog yn ôl, ac mae’r geiriau a gerfiwyd ar ei gofeb yn dweud iddo gymryd etifeddiaeth Powys o afael y Saeson, â thân ac â’i gleddyf.",
    "Mae Piler Eliseg yn sefyll ar ei dwmpath ger Abaty Glyn y Groes o hyd. Olrheiniai ei arysgrif Ladin hir, sydd bellach wedi treulio ond a gopïwyd yn 1696 gan Edward Lhuyd, linach Powys yn ôl at Facsen Wledig a Gwrtheyrn, ac mae’n un o gofnodion cynnar mwyaf gwerthfawr Cymru."]),
 P("cyngen", "kings", "d. 855", "Cyngen ap Cadell", "Cyngen ap Cadell", "King who raised the Pillar of Eliseg", "Y brenin a gododd Biler Eliseg", "Cyngen_ap_Cadell", "rulers",
   "The last king of the old line of Powys. He raised the Pillar of Eliseg to honour his forefather and died on pilgrimage in Rome.",
   "Brenin olaf hen linach Powys. Cododd Biler Eliseg i anrhydeddu ei gyndad a bu farw ar bererindod yn Rhufain.",
   ["Cyngen ruled Powys for over forty years. He set up the great stone cross now called the Pillar of Eliseg, and had carved on it the deeds of his great-grandfather Elisedd and the line of the kings of Powys, ending with a blessing on all who read it.",
    "In his old age he went on pilgrimage to Rome, where he died in 855. His sister Nest married Merfyn Frych of Gwynedd, and through her son Rhodri Mawr the blood of the old kings of Powys passed into the princes who ruled Wales for the next four hundred years."],
   ["Rheolodd Cyngen Bowys am dros ddeugain mlynedd. Cododd y groes garreg fawr a elwir heddiw’n Biler Eliseg, a pheri cerfio arni weithredoedd ei orhendaid Elisedd a llinach brenhinoedd Powys, gan orffen â bendith ar bawb a’i darllenai.",
    "Yn ei henaint aeth ar bererindod i Rufain, lle bu farw yn 855. Priododd ei chwaer Nest â Merfyn Frych o Wynedd, a thrwy ei mab hi, Rhodri Mawr, aeth gwaed hen frenhinoedd Powys i’r tywysogion a reolodd Gymru am y pedwar can mlynedd nesaf."]),
 P("anarawd", "kings", "d. 916", "Anarawd ap Rhodri", "Anarawd ap Rhodri", "Avenger of Rhodri Mawr", "Dialydd Rhodri Mawr", "Anarawd_ap_Rhodri", "rulers",
   "The son of Rhodri Mawr who beat the Mercians at the battle of Conwy in 881, a victory remembered as Dial Rhodri, the vengeance for Rhodri.",
   "Mab Rhodri Mawr a drechodd y Mersiaid ym mrwydr Conwy yn 881, buddugoliaeth a gofir fel Dial Rhodri.",
   ["When Rhodri Mawr was killed by the English in 878, his son Anarawd took up the kingdom of Gwynedd. Three years later the Mercians invaded again, and at the mouth of the Conwy Anarawd crushed them.",
    "The Welsh chronicles called the battle God’s vengeance for Rhodri. Anarawd went on to make Gwynedd safe for a generation, and his descendants, the line of Aberffraw, ruled Gwynedd until the last prince, Llywelyn ap Gruffudd."],
   ["Pan laddwyd Rhodri Mawr gan y Saeson yn 878, cymerodd ei fab Anarawd deyrnas Gwynedd. Dair blynedd yn ddiweddarach ymosododd y Mersiaid eto, ac yn aber Conwy chwalodd Anarawd hwy.",
    "Galwodd cronicl Cymru’r frwydr yn ddial Duw am Rodri. Aeth Anarawd ymlaen i wneud Gwynedd yn ddiogel am genhedlaeth, a’i ddisgynyddion, llinach Aberffraw, a reolodd Wynedd hyd y tywysog olaf, Llywelyn ap Gruffudd."]),
 P("owain-ap-hywel", "kings", "d. 988", "Owain ap Hywel Dda", "Owain ap Hywel Dda", "King of Deheubarth", "Brenin Deheubarth", "Owain_ap_Hywel", "rulers",
   "The son of Hywel Dda, who ruled Deheubarth for over thirty years. The oldest Welsh chronicle and royal pedigrees are thought to have been written down at his court.",
   "Mab Hywel Dda, a reolodd Ddeheubarth am dros ddeng mlynedd ar hugain. Credir mai yn ei lys ef yr ysgrifennwyd y cronicl a’r achau brenhinol Cymraeg hynaf.",
   ["Owain inherited his father’s southern kingdom of Deheubarth in 950 and ruled it until his old age, when his warrior son Maredudd took up the fight for him.",
    "Scholars believe that the earliest version of the Annales Cambriae, the Welsh Annals, and the oldest collection of Welsh royal pedigrees were put together at Owain’s court, and they begin his own family tree with his father, Hywel Dda. Much of what we know of early Wales has come down to us through them."],
   ["Etifeddodd Owain deyrnas ddeheuol ei dad, Deheubarth, yn 950 a’i rheoli hyd ei henaint, pan gymerodd ei fab rhyfelgar Maredudd y frwydr drosto.",
    "Cred ysgolheigion mai yn llys Owain y lluniwyd y fersiwn cynharaf o’r Annales Cambriae, Blwydd-lyfr Cymru, a’r casgliad hynaf o achau brenhinol Cymru, ac maen nhw’n dechrau ei goeden deulu ei hun gyda’i dad, Hywel Dda. Drwyddynt hwy y daeth llawer o’r hyn a wyddom am Gymru gynnar i lawr atom."]),
 P("maredudd-ab-owain", "kings", "d. 999", "Maredudd ab Owain", "Maredudd ab Owain", "King of most of Wales", "Brenin y rhan fwyaf o Gymru", "Maredudd_ab_Owain", "rulers",
   "Grandson of Hywel Dda who ruled both Deheubarth and Gwynedd, the most powerful Welsh king of his day. He stood by his people through years of Viking raids.",
   "Ŵyr Hywel Dda a reolodd Ddeheubarth a Gwynedd, brenin Cymreig mwyaf grymus ei ddydd. Safodd gyda’i bobl drwy flynyddoedd o ymosodiadau’r Llychlynwyr.",
   ["Maredudd took Gwynedd in 986 and joined it to his father’s Deheubarth, ruling most of Wales as his grandfather Hywel Dda had done. His was a hard time, with Viking fleets raiding the coasts and St Davids itself plundered.",
    "When Viking raiders carried off two thousand people from Anglesey in 987, Maredudd took the burden on himself, and the chronicle records that he paid the raiders a tribute of a penny a head. The Welsh chronicle called him the most famous king of the Britons."],
   ["Cymerodd Maredudd Wynedd yn 986 a’i huno â Deheubarth ei dad, gan reoli’r rhan fwyaf o Gymru fel y gwnaethai ei daid Hywel Dda. Cyfnod caled oedd ei gyfnod ef, gyda llynges y Llychlynwyr yn ysbeilio’r glannau a Thyddewi ei hun yn cael ei hanrheithio.",
    "Pan gludodd ysbeilwyr Llychlynnaidd ddwy fil o bobl o Fôn yn 987, cymerodd Maredudd y baich arno’i hun, ac mae’r cronicl yn cofnodi iddo dalu teyrnged o geiniog y pen i’r ysbeilwyr. Galwodd cronicl Cymru ef yn frenin enwocaf y Brythoniaid."]),
 P("llywelyn-ap-seisyll", "kings", "d. 1023", "Llywelyn ap Seisyll", "Llywelyn ap Seisyll", "King of a golden age", "Brenin oes aur", "Llywelyn_ap_Seisyll", "rulers",
   "King of Gwynedd and Deheubarth, and father of Gruffudd ap Llywelyn. The Welsh chronicle says that in his days the land was rich from sea to sea.",
   "Brenin Gwynedd a Deheubarth, a thad Gruffudd ap Llywelyn. Dywed cronicl Cymru fod y wlad yn gyfoethog o fôr i fôr yn ei ddyddiau ef.",
   ["Llywelyn ap Seisyll rose to rule Gwynedd around 1018 and then won Deheubarth, beating the pretender Rhain at Abergwili in 1022.",
    "The chroniclers remembered his short reign as a golden age. In his time, they wrote, the earth bore double, there was no beggar and no empty house from sea to sea. His son Gruffudd ap Llywelyn went on to become the only king to rule the whole of Wales."],
   ["Cododd Llywelyn ap Seisyll i reoli Gwynedd tua 1018 ac yna enillodd Ddeheubarth, gan drechu’r hawliwr Rhain yn Abergwili yn 1022.",
    "Cofiai’r croniclwyr ei deyrnasiad byr fel oes aur. Yn ei amser ef, meddent, dyblai’r ddaear ei chnwd, ac nid oedd na chardotyn na thŷ gwag o fôr i fôr. Aeth ei fab Gruffudd ap Llywelyn ymlaen i fod yr unig frenin i reoli Cymru gyfan."]),
 P("bleddyn-ap-cynfyn", "kings", "d. 1075", "Bleddyn ap Cynfyn", "Bleddyn ap Cynfyn", "The gentlest of kings", "Y mwynaf o frenhinoedd", "Bleddyn_ap_Cynfyn", "rulers",
   "King of Gwynedd and Powys who revised the laws of Hywel Dda. The Welsh chronicle called him the gentlest and most merciful of kings, and founder of the royal house of Powys.",
   "Brenin Gwynedd a Phowys a ddiwygiodd gyfreithiau Hywel Dda. Galwodd cronicl Cymru ef y mwynaf a’r trugarocaf o frenhinoedd, a sefydlydd tŷ brenhinol Powys.",
   ["Bleddyn took Gwynedd and Powys in 1063 and held them for twelve years, through the first fierce years of the Norman conquest of England, and he joined the English rebels against William the Conqueror.",
    "Welsh lawbooks record changes he made to the laws of Hywel Dda. The chronicle mourned him as the gentlest and most merciful of kings, who did harm to none unless wronged, generous to all and a protector of churches. The princes of Powys traced their line from him."],
   ["Cymerodd Bleddyn Wynedd a Phowys yn 1063 a’u dal am ddeuddeng mlynedd, drwy flynyddoedd ffyrnig cyntaf concwest y Normaniaid ar Loegr, ac ymunodd â gwrthryfelwyr Lloegr yn erbyn Gwilym Goncwerwr.",
    "Mae llyfrau cyfraith Cymru yn cofnodi newidiadau a wnaeth i gyfreithiau Hywel Dda. Galarodd y cronicl amdano fel y mwynaf a’r trugarocaf o frenhinoedd, na wnâi niwed i neb oni chaffai gam, hael wrth bawb ac amddiffynnydd eglwysi. O’i linach ef y tarddai tywysogion Powys."]),
 P("sulien", "kings", "1011–1091", "Sulien", "Sulien", "The wisest of the Britons", "Y doethaf o’r Brythoniaid", "Sulien", "learning",
   "Scholar and bishop of St Davids who studied for many years in Scotland and Ireland and made Llanbadarn Fawr a famous school. Father of Rhygyfarch.",
   "Ysgolhaig ac esgob Tyddewi a fu’n astudio am flynyddoedd yn yr Alban ac Iwerddon a gwneud Llanbadarn Fawr yn ysgol enwog. Tad Rhygyfarch.",
   ["Sulien was born in Ceredigion and set out as a young man to study, first in Scotland and then for years in Ireland. He came home to Llanbadarn Fawr, where his school drew students from all over Wales, and twice he was made bishop of St Davids.",
    "He and his sons, Rhygyfarch, Ieuan and Daniel, copied and decorated books that still survive, among them a psalter and a copy of Saint Augustine. When he died in 1091 the chronicle called him the wisest of the Britons."],
   ["Ganed Sulien yng Ngheredigion a chychwynnodd yn llanc i astudio, yn gyntaf yn yr Alban ac yna am flynyddoedd yn Iwerddon. Daeth adref i Lanbadarn Fawr, lle denai ei ysgol fyfyrwyr o bob rhan o Gymru, a dwywaith fe’i gwnaed yn esgob Tyddewi.",
    "Bu ef a’i feibion, Rhygyfarch, Ieuan a Daniel, yn copïo ac addurno llyfrau sydd wedi goroesi o hyd, yn eu plith sallwyr a chopi o Awstin Sant. Pan fu farw yn 1091 galwodd y cronicl ef y doethaf o’r Brythoniaid."]),
]

PEOPLE += [
 # ---------- The Age of Princes ----------
 P("meilyr-brydydd", "medieval", "fl. 1100–1137", "Meilyr Brydydd", "Meilyr Brydydd", "First of the Poets of the Princes", "Cyntaf Beirdd y Tywysogion", "Meilyr_Brydydd", "words",
   "Court poet of Gruffudd ap Cynan and the first of the Poets of the Princes, whose great poetry runs for two hundred years until the fall of Llywelyn.",
   "Pencerdd Gruffudd ap Cynan a’r cyntaf o Feirdd y Tywysogion, y mae eu barddoniaeth fawr yn ymestyn am ddau gan mlynedd hyd gwymp Llywelyn.",
   ["Meilyr was chief poet at the court of Gruffudd ap Cynan, king of Gwynedd. His elegy for Gruffudd, who died in 1137, is one of the first poems of the Gogynfeirdd, the Poets of the Princes.",
    "On his own deathbed he composed a poem asking to be buried on Bardsey, the island of twenty thousand saints, within sound of the sea. His son Gwalchmai and grandsons carried on his art, and the line of court poets he began sang the praises of the princes until 1282."],
   ["Meilyr oedd pencerdd llys Gruffudd ap Cynan, brenin Gwynedd. Ei farwnad i Ruffudd, a fu farw yn 1137, yw un o gerddi cyntaf y Gogynfeirdd, Beirdd y Tywysogion.",
    "Ar ei wely angau cyfansoddodd gerdd yn gofyn am gael ei gladdu ar Enlli, ynys yr ugain mil o saint, o fewn sŵn y môr. Parhaodd ei fab Gwalchmai a’i wyrion ei gelfyddyd, a chanodd llinach y beirdd llys a ddechreuodd glod y tywysogion hyd 1282."]),
 P("cynddelw", "medieval", "fl. 1155–1195", "Cynddelw Brydydd Mawr", "Cynddelw Brydydd Mawr", "The great poet", "Y prydydd mawr", "Cynddelw_Brydydd_Mawr", "words",
   "The greatest of the Poets of the Princes, who sang for the rulers of Powys, Gwynedd and Deheubarth. More of his poetry survives than of any other poet of the age.",
   "Y mwyaf o Feirdd y Tywysogion, a ganodd i reolwyr Powys, Gwynedd a Deheubarth. Mae mwy o’i farddoniaeth ef wedi goroesi nag o waith unrhyw fardd arall yr oes.",
   ["Cynddelw was called Prydydd Mawr, the Great Poet, and he earned the name. He sang for Madog ap Maredudd of Powys, for Owain Gwynedd and for the Lord Rhys, and his elegies, praise poems and religious verse fill a whole volume.",
    "He was proud of his craft and of the poet’s high place at court. His famous poem to the warband of Powys, Gwelygorddau Powys, celebrates the privileges of the men of Powys, and his deathbed poem to God is one of the finest of the age."],
   ["Galwyd Cynddelw yn Brydydd Mawr, ac fe haeddodd yr enw. Canodd i Fadog ap Maredudd o Bowys, i Owain Gwynedd ac i’r Arglwydd Rhys, ac mae ei farwnadau, ei gerddi mawl a’i gerddi crefyddol yn llenwi cyfrol gyfan.",
    "Roedd yn falch o’i grefft ac o le uchel y bardd yn y llys. Mae ei gerdd enwog Gwelygorddau Powys yn dathlu breintiau gwŷr Powys, a’i gerdd i Dduw ar ei wely angau yn un o’r goreuon yn yr oes."]),
 P("meddygon-myddfai", "medieval", "fl. 13th century", "Rhiwallon and the Physicians of Myddfai", "Rhiwallon a Meddygon Myddfai", "Healers of Myddfai", "Iachawyr Myddfai", "Physicians_of_Myddfai", "science",
   "Rhiwallon, physician to Rhys Gryg, and his sons, whose cures were written down in Welsh in the Middle Ages. Welsh tradition holds that their mother was the Lady of Llyn y Fan Fach.",
   "Rhiwallon, meddyg Rhys Gryg, a’i feibion, y cofnodwyd eu meddyginiaethau yn Gymraeg yn yr Oesoedd Canol. Yn ôl traddodiad Cymru eu mam oedd Morwyn Llyn y Fan Fach.",
   ["Rhiwallon was physician to Rhys Gryg, lord of Deheubarth, who gave him land at Myddfai below the Black Mountain. He and his sons Cadwgan, Gruffudd and Einion wrote down their remedies, and the Red Book of Hergest preserves them, among the oldest medical writing in Welsh.",
    "Welsh tradition holds that their mother rose from the lake of Llyn y Fan Fach, married a young farmer and taught her sons the healing power of plants before she returned to the water. Their descendants practised as doctors in Myddfai for some six hundred years."],
   ["Rhiwallon oedd meddyg Rhys Gryg, arglwydd Deheubarth, a roddodd dir iddo ym Myddfai dan y Mynydd Du. Cofnododd ef a’i feibion Cadwgan, Gruffudd ac Einion eu meddyginiaethau, ac mae Llyfr Coch Hergest yn eu cadw, ymhlith yr ysgrifennu meddygol hynaf yn Gymraeg.",
    "Yn ôl traddodiad Cymru cododd eu mam o Lyn y Fan Fach, priododd ffermwr ifanc a dysgodd i’w meibion rym iachusol planhigion cyn dychwelyd i’r dŵr. Bu eu disgynyddion yn feddygon ym Myddfai am ryw chwe chan mlynedd."]),
 P("ednyfed-fychan", "medieval", "d. 1246", "Ednyfed Fychan", "Ednyfed Fychan", "Steward of Llywelyn the Great", "Distain Llywelyn Fawr", "Ednyfed_Fychan", "politics",
   "The chief minister of Llywelyn the Great and his son Dafydd for over thirty years, and the forefather of the Tudors.",
   "Prif weinidog Llywelyn Fawr a’i fab Dafydd am dros ddeng mlynedd ar hugain, a chyndad y Tuduriaid.",
   ["Ednyfed Fychan became distain, or steward, of Gwynedd around 1215 and was Llywelyn the Great’s right hand in war and peace. He led embassies to the English king, went on crusade, and helped turn Gwynedd into a true Welsh state.",
    "Welsh tradition holds that he won his coat of arms, three Englishmen’s heads, in battle. His family became the leading servants of the princes, and from his line came Owain Tudur and so Henry VII, the Welsh king who took the throne of England in 1485."],
   ["Daeth Ednyfed Fychan yn ddistain Gwynedd tua 1215 a bu’n llaw dde i Lywelyn Fawr mewn rhyfel a heddwch. Arweiniodd lysgenadaethau at frenin Lloegr, aeth ar groesgad, a helpodd i droi Gwynedd yn wladwriaeth Gymreig go iawn.",
    "Yn ôl traddodiad Cymru enillodd ei arfbais, tri phen Sais, ar faes y gad. Daeth ei deulu yn brif weision y tywysogion, ac o’i linach ef y daeth Owain Tudur ac felly Harri VII, y brenin o Gymro a gipiodd orsedd Lloegr yn 1485."]),
 P("madog-ap-llywelyn", "medieval", "fl. 1294–1295", "Madog ap Llywelyn", "Madog ap Llywelyn", "Prince of Wales of the 1294 rising", "Tywysog Cymru yng ngwrthryfel 1294", "Madog_ap_Llywelyn", "heroes",
   "Leader of the great Welsh rising of 1294 against Edward I, twelve years after the fall of Llywelyn. He called himself Prince of Wales and took Caernarfon.",
   "Arweinydd gwrthryfel mawr y Cymry yn 1294 yn erbyn Edward I, ddeuddeng mlynedd ar ôl cwymp Llywelyn. Galwodd ei hun yn Dywysog Cymru a chipiodd Gaernarfon.",
   ["In the autumn of 1294 Wales rose in arms from end to end. In the north the leader was Madog ap Llywelyn, of the royal house of Gwynedd. His men stormed Caernarfon, burned the new town and tore down its walls, while the castles of Edward I were besieged across the country.",
    "In January 1295, at Penmachno, Madog sealed a grant of land as ‘Prince of Wales’, and the document still survives. Edward had to come in person with a great army to end the rising. Madog was taken to London, but he had shown that the spirit of Llywelyn was not dead."],
   ["Yn hydref 1294 cododd Cymru mewn arfau o un pen i’r llall. Yn y gogledd yr arweinydd oedd Madog ap Llywelyn, o dŷ brenhinol Gwynedd. Ymosododd ei wŷr ar Gaernarfon, llosgi’r dref newydd a thynnu ei muriau i lawr, tra gwarchaewyd cestyll Edward I ar draws y wlad.",
    "Ym mis Ionawr 1295, ym Mhenmachno, seliodd Madog roddiad tir fel ‘Tywysog Cymru’, ac mae’r ddogfen wedi goroesi o hyd. Bu’n rhaid i Edward ddod ei hun gyda byddin fawr i roi terfyn ar y gwrthryfel. Aed â Madog i Lundain, ond roedd wedi dangos nad oedd ysbryd Llywelyn wedi marw."]),
 P("hywel-y-fwyall", "medieval", "d. c. 1381", "Sir Hywel ap Gruffudd", "Syr Hywel y Fwyall", "Hywel of the Axe", "Hywel y Fwyall", "Hywel_ap_Gruffudd_(Hywel_y_Fwyall)", "heroes",
   "The Welsh knight who fought with a great battle-axe at Poitiers in 1356. Welsh tradition holds that his axe was honoured with a dish of food every day.",
   "Y marchog o Gymro a ymladdodd â bwyell ryfel fawr ym Mhoitiers yn 1356. Yn ôl traddodiad Cymru anrhydeddwyd ei fwyell â dysglaid o fwyd bob dydd.",
   ["Hywel ap Gruffudd, from Eifionydd, won fame in the wars in France, where thousands of Welshmen fought as archers and spearmen. At the battle of Poitiers in 1356 he fought with a great axe, and Welsh tradition holds that it was he who took the French king prisoner.",
    "He was knighted and made constable of Criccieth Castle. The poet Iolo Goch praised him, and Welsh tradition tells that his axe was honoured with a dish of food served before it each day, which was then given to the poor."],
   ["Enillodd Hywel ap Gruffudd, o Eifionydd, enwogrwydd yn y rhyfeloedd yn Ffrainc, lle ymladdai miloedd o Gymry fel saethwyr a gwaywffonwyr. Ym mrwydr Poitiers yn 1356 ymladdodd â bwyell fawr, ac yn ôl traddodiad Cymru ef a gymerodd frenin Ffrainc yn garcharor.",
    "Fe’i gwnaed yn farchog ac yn gwnstabl Castell Cricieth. Canodd y bardd Iolo Goch ei glod, ac mae traddodiad Cymru’n adrodd bod ei fwyell yn cael ei hanrhydeddu â dysglaid o fwyd o’i blaen bob dydd, a roddid wedyn i’r tlodion."]),
 P("rhys-gwilym-ap-tudur", "medieval", "fl. 1401", "Rhys and Gwilym ap Tudur", "Rhys a Gwilym ap Tudur", "Captors of Conwy Castle", "Cipwyr Castell Conwy", "Conwy_Castle", "heroes",
   "Cousins of Owain Glyndŵr who seized mighty Conwy Castle on Good Friday 1401 with a handful of men, while the garrison was at church.",
   "Cefndryd Owain Glyndŵr a gipiodd Gastell Conwy cadarn ar Ddydd Gwener y Groglith 1401 gydag ychydig o wŷr, tra oedd y garsiwn yn yr eglwys.",
   ["Rhys and Gwilym ap Tudur of Penmynydd in Anglesey were cousins of Owain Glyndŵr and uncles of the Owain Tudur who founded the Tudor line. On Good Friday 1401, while almost all the garrison of Conwy were at church, a carpenter came to the castle gate, and with him came forty Welshmen, who took the castle.",
    "They held one of the strongest castles in Europe for three months against the Prince of Wales and his army, and gave it up only on their own terms. It was one of the boldest strokes of Glyndŵr’s rising and set the whole of the north alight."],
   ["Roedd Rhys a Gwilym ap Tudur o Benmynydd ym Môn yn gefndryd i Owain Glyndŵr ac yn ewythrod i’r Owain Tudur a sefydlodd linach y Tuduriaid. Ar Ddydd Gwener y Groglith 1401, tra oedd bron y cyfan o garsiwn Conwy yn yr eglwys, daeth saer at borth y castell, a chydag ef daeth deugain o Gymry, a chipiwyd y castell.",
    "Daliasant un o gestyll cadarnaf Ewrop am dri mis yn erbyn Tywysog Cymru a’i fyddin, a’i ildio dim ond ar eu telerau eu hunain. Roedd yn un o gampau mwyaf beiddgar gwrthryfel Glyndŵr a rhoes y gogledd i gyd ar dân."]),

 # ---------- Tudor and Stuart Wales ----------
 P("richard-davies", "tudor", "c. 1505–1581", "Richard Davies", "Richard Davies", "Bishop and translator", "Esgob a chyfieithydd", "Richard_Davies_(bishop)", "faith",
   "Bishop of St Davids who translated the New Testament into Welsh with William Salesbury in 1567, and wrote a famous letter to the Welsh people about their history.",
   "Esgob Tyddewi a gyfieithodd y Testament Newydd i’r Gymraeg gyda William Salesbury yn 1567, ac a ysgrifennodd lythyr enwog at y Cymry am eu hanes.",
   ["Richard Davies was born in the Conwy valley, son of a curate. In exile under Queen Mary, he came home under Elizabeth to be bishop first of St Asaph and then of St Davids, and he worked hard for the act of 1563 that ordered the Bible to be put into Welsh.",
    "At his palace at Abergwili he and William Salesbury translated the New Testament, published in 1567. Davies translated several books himself and wrote its preface, the Epistol at y Cymry, a proud letter to the Welsh reminding them of the ancient faith of the Britons."],
   ["Ganed Richard Davies yn nyffryn Conwy, yn fab i gurad. Bu’n alltud dan y Frenhines Mari, a daeth adref dan Elisabeth yn esgob Llanelwy yn gyntaf ac yna Tyddewi, a gweithiodd yn galed dros ddeddf 1563 a orchmynnodd roi’r Beibl yn Gymraeg.",
    "Yn ei blas yn Abergwili cyfieithodd ef a William Salesbury y Testament Newydd, a gyhoeddwyd yn 1567. Cyfieithodd Davies sawl llyfr ei hun ac ysgrifennu’r rhagair, yr Epistol at y Cymry, llythyr balch yn atgoffa’r Cymry o hen ffydd y Brythoniaid."]),
 P("edmwnd-prys", "tudor", "1544–1623", "Edmwnd Prys", "Edmwnd Prys", "Poet of the Welsh psalms", "Bardd y Salmau Cân", "Edmund_Prys", "words",
   "Archdeacon of Merioneth whose Welsh metrical psalms of 1621 were the first made for whole congregations to sing. Some are still sung today.",
   "Archddiacon Meirionnydd y bu ei Salmau Cân yn 1621 y salmau Cymraeg cyntaf i gynulleidfaoedd cyfan eu canu. Cenir rhai ohonynt hyd heddiw.",
   ["Edmwnd Prys was born near Llanrwst and studied at Cambridge with William Morgan, whom he helped with the Welsh Bible. As archdeacon of Merioneth he lived at Maentwrog and was a master of strict-metre poetry.",
    "His great gift to Wales was the Salmau Cân, the psalms in free Welsh verse, printed with the Book of Common Prayer in 1621 so that whole congregations could sing them. They were the beginning of the great Welsh tradition of hymn singing, and several of his psalms are still sung."],
   ["Ganed Edmwnd Prys ger Llanrwst ac astudiodd yng Nghaergrawnt gyda William Morgan, a helpodd gyda’r Beibl Cymraeg. Fel archddiacon Meirionnydd bu’n byw ym Maentwrog ac roedd yn feistr ar y canu caeth.",
    "Ei rodd fawr i Gymru oedd y Salmau Cân, y salmau ar fesur rhydd Cymraeg, a argraffwyd gyda’r Llyfr Gweddi Gyffredin yn 1621 er mwyn i gynulleidfaoedd cyfan eu canu. Dyna ddechrau traddodiad mawr canu emynau yng Nghymru, a chenir nifer o’i salmau o hyd."],
   first=("wales", "The first Welsh psalms for whole congregations to sing", "Y salmau Cymraeg cyntaf i gynulleidfaoedd cyfan eu canu", 1621)),
 P("sion-dafydd-rhys", "tudor", "1534–c. 1619", "Siôn Dafydd Rhys", "Siôn Dafydd Rhys", "Doctor and grammarian", "Meddyg a gramadegydd", "John_Davies_Rhys", "learning",
   "Anglesey doctor who studied in Italy and wrote books in Italian, then a great grammar of Welsh in 1592 to show the world the riches of the language.",
   "Meddyg o Fôn a astudiodd yn yr Eidal ac ysgrifennu llyfrau yn Eidaleg, ac yna ramadeg mawr y Gymraeg yn 1592 i ddangos cyfoeth yr iaith i’r byd.",
   ["Siôn Dafydd Rhys was born in Llanfaethlu in Anglesey, studied at Oxford and took his doctorate in medicine at Siena in Italy. He wrote a Latin grammar of Italian and books in Italian, among the first by any Briton.",
    "Home in Wales, he practised medicine at Brecon and wrote Cambrobrytannicae Cymraecaeve Linguae Institutiones, a grand grammar of Welsh and its strict-metre poetry, published in 1592. Written in Latin, it set out the rules of the bards so that scholars across Europe could see that Welsh was a language of learning."],
   ["Ganed Siôn Dafydd Rhys yn Llanfaethlu ym Môn, astudiodd yn Rhydychen a chymerodd ei ddoethuriaeth mewn meddygaeth yn Siena yn yr Eidal. Ysgrifennodd ramadeg Lladin o’r Eidaleg a llyfrau yn Eidaleg, ymhlith y cyntaf gan unrhyw Frython.",
    "Adref yng Nghymru bu’n feddyg yn Aberhonddu ac ysgrifennodd Cambrobrytannicae Cymraecaeve Linguae Institutiones, gramadeg mawreddog o’r Gymraeg a’i cherdd dafod, a gyhoeddwyd yn 1592. Fe’i hysgrifennwyd yn Lladin i osod rheolau’r beirdd fel y gallai ysgolheigion ar draws Ewrop weld bod y Gymraeg yn iaith dysg."]),
 P("rhys-prichard", "tudor", "1579–1644", "Rhys Prichard", "Rhys Prichard, yr Hen Ficer", "The Old Vicar", "Yr Hen Ficer", "Rhys_Prichard", "words",
   "The vicar of Llanymddyfri whose simple, warm verses, Canwyll y Cymry, were learned by heart in Welsh homes for two hundred years.",
   "Ficer Llanymddyfri y dysgwyd ei benillion syml, cynnes, Canwyll y Cymry, ar gof mewn cartrefi ledled Cymru am ddau gan mlynedd.",
   ["Rhys Prichard was vicar of Llanymddyfri in Carmarthenshire. Seeing that few of his people could read, he put the teaching of the faith into short, homely rhyming verses that anyone could remember and sing.",
    "After his death they were gathered and printed as Canwyll y Cymry, the Candle of the Welsh. Next to the Bible it was the best-loved book in Wales, reprinted again and again, and families who owned no other book could recite the Old Vicar’s verses."],
   ["Roedd Rhys Prichard yn ficer Llanymddyfri yn Sir Gaerfyrddin. Gan weld mai ychydig o’i bobl a fedrai ddarllen, gosododd ddysgeidiaeth y ffydd mewn penillion byr, cartrefol y gallai unrhyw un eu cofio a’u canu.",
    "Wedi ei farw casglwyd hwy a’u hargraffu fel Canwyll y Cymry. Yn nesaf at y Beibl hwn oedd y llyfr anwylaf yng Nghymru, a’i ailargraffu dro ar ôl tro, a gallai teuluoedd heb yr un llyfr arall adrodd penillion yr Hen Ficer."]),
 P("ellis-wynne", "tudor", "1671–1734", "Ellis Wynne", "Ellis Wynne", "Author of the Visions of the Sleeping Bard", "Awdur Gweledigaetheu y Bardd Cwsc", "Ellis_Wynne", "words",
   "The Merioneth clergyman whose Gweledigaetheu y Bardd Cwsc (1703) is one of the great classics of Welsh prose.",
   "Y clerigwr o Feirionnydd y mae ei Weledigaetheu y Bardd Cwsc (1703) yn un o glasuron mawr rhyddiaith Gymraeg.",
   ["Ellis Wynne was born at Y Lasynys, a farmhouse near Harlech, and studied at Oxford before becoming rector of Llanfair near Harlech.",
    "In 1703 he published Gweledigaetheu y Bardd Cwsc, the Visions of the Sleeping Bard, in which a dreaming poet is led through the City of Destruction, the land of Death and Hell itself. Its vivid, funny, biting Welsh has made it a classic, and Y Lasynys is now open to visitors."],
   ["Ganed Ellis Wynne yn Y Lasynys, ffermdy ger Harlech, ac astudiodd yn Rhydychen cyn dod yn rheithor Llanfair ger Harlech.",
    "Yn 1703 cyhoeddodd Gweledigaetheu y Bardd Cwsc, lle mae bardd yn breuddwydio ac yn cael ei arwain drwy Ddinas Distryw, gwlad Angau ac Uffern ei hun. Mae ei Gymraeg byw, doniol a llym wedi’i wneud yn glasur, ac mae’r Lasynys bellach ar agor i ymwelwyr."]),
 P("theophilus-evans", "tudor", "1693–1767", "Theophilus Evans", "Theophilus Evans", "Historian of the Welsh", "Hanesydd y Cymry", "Theophilus_Evans", "words",
   "Clergyman whose Drych y Prif Oesoedd (1716) told the story of the ancient Britons with pride and became one of the most popular Welsh books ever written.",
   "Clerigwr yr adroddodd ei Ddrych y Prif Oesoedd (1716) stori’r hen Frythoniaid gyda balchder. Daeth yn un o’r llyfrau Cymraeg mwyaf poblogaidd erioed.",
   ["Theophilus Evans was born at Penywenallt in Ceredigion and served as a clergyman in Breconshire, where he also wrote about the healing waters of Llanwrtyd Wells.",
    "His Drych y Prif Oesoedd, the Mirror of the First Ages, told the history of the Britons from their beginnings to the Saxon wars in lively, colourful Welsh. It was read and reread by ordinary people for two centuries and gave generations of Welsh readers pride in their ancient past."],
   ["Ganed Theophilus Evans ym Mhenywenallt yng Ngheredigion a bu’n glerigwr yn Sir Frycheiniog, lle ysgrifennodd hefyd am ddyfroedd iachusol Llanwrtyd.",
    "Adroddai ei Ddrych y Prif Oesoedd hanes y Brythoniaid o’u dechreuad hyd ryfeloedd y Saeson mewn Cymraeg bywiog, lliwgar. Fe’i darllenwyd dro ar ôl tro gan bobl gyffredin am ddwy ganrif, a rhoes falchder yn eu gorffennol hynafol i genedlaethau o ddarllenwyr Cymraeg."]),
 P("isaac-carter", "tudor", "d. 1741", "Isaac Carter", "Isaac Carter", "First printer in Wales", "Yr argraffydd cyntaf yng Nghymru", "Isaac_Carter", "enterprise",
   "Printer who set up the first lasting printing press in Wales, at Trefhedyn near Newcastle Emlyn, in 1718.",
   "Argraffydd a sefydlodd y wasg argraffu barhaol gyntaf yng Nghymru, yn Nhrefhedyn ger Castellnewydd Emlyn, yn 1718.",
   ["Until the eighteenth century, almost every Welsh book had to be printed in London, Oxford or Shrewsbury. In 1718 Isaac Carter set up a press at Trefhedyn, by the Teifi near Newcastle Emlyn, the first lasting press in Wales.",
    "His first works were Welsh ballads and religious books for ordinary readers. He later moved his press to Carmarthen, which became a great printing town, and within a century presses were busy in towns across Wales, turning out Welsh books, magazines and newspapers."],
   ["Hyd y ddeunawfed ganrif bu’n rhaid argraffu bron pob llyfr Cymraeg yn Llundain, Rhydychen neu’r Amwythig. Yn 1718 sefydlodd Isaac Carter wasg yn Nhrefhedyn, ar lan Teifi ger Castellnewydd Emlyn, y wasg barhaol gyntaf yng Nghymru.",
    "Baledi Cymraeg a llyfrau crefyddol i ddarllenwyr cyffredin oedd ei waith cyntaf. Symudodd ei wasg wedyn i Gaerfyrddin, a ddaeth yn dref argraffu fawr, ac o fewn canrif roedd gweisg yn brysur mewn trefi ledled Cymru yn cynhyrchu llyfrau, cylchgronau a phapurau newydd Cymraeg."],
   first=("wales", "The first lasting printing press in Wales", "Y wasg argraffu barhaol gyntaf yng Nghymru", 1718)),

 # ---------- Industrial Wales ----------
 P("sarah-siddons", "industrial", "1755–1831", "Sarah Siddons", "Sarah Siddons", "Queen of the stage", "Brenhines y llwyfan", "Sarah_Siddons", "stage",
   "Born in an inn at Brecon, she became the greatest actress of her age, famous above all as Lady Macbeth.",
   "Fe’i ganed mewn tafarn yn Aberhonddu a daeth yn actores fwyaf ei hoes, yn enwog yn anad dim fel Lady Macbeth.",
   ["Sarah Kemble was born in 1755 at the Shoulder of Mutton inn in Brecon, while her parents’ company of travelling players was in the town. She acted from childhood, married the actor William Siddons and went on the stage in London.",
    "From 1782 she was the queen of Drury Lane. Audiences wept and fainted at her tragedies, and her sleepwalking Lady Macbeth became legendary. Reynolds painted her as the Tragic Muse, and the inn where she was born in Brecon still bears her name."],
   ["Ganed Sarah Kemble yn 1755 yn nhafarn y Shoulder of Mutton yn Aberhonddu, tra oedd cwmni chwaraewyr teithiol ei rhieni yn y dref. Actiodd o’i phlentyndod, priododd yr actor William Siddons ac aeth ar y llwyfan yn Llundain.",
    "O 1782 hi oedd brenhines Drury Lane. Wylai a llewygai’r gynulleidfa yn ei thrasiedïau, a daeth ei Lady Macbeth yn cerdded yn ei chwsg yn chwedlonol. Paentiodd Reynolds hi fel Awen y Drasiedi, ac mae’r dafarn lle y’i ganed yn Aberhonddu yn dwyn ei henw o hyd."]),
 P("morgan-john-rhys", "industrial", "1760–1804", "Morgan John Rhys", "Morgan John Rhys", "Radical and founder of Cambria", "Radical a sefydlydd Cambria", "Morgan_John_Rhys", "politics",
   "Baptist minister from Glamorgan who campaigned against slavery, published one of the first Welsh magazines and founded a Welsh settlement, Cambria, in Pennsylvania.",
   "Gweinidog o’r Bedyddwyr o Forgannwg a ymgyrchodd yn erbyn caethwasiaeth, a gyhoeddodd un o’r cylchgronau Cymraeg cyntaf ac a sefydlodd wladfa Gymreig, Cambria, ym Mhensylfania.",
   ["Morgan John Rhys was born near Llanbradach and became a Baptist minister. Fired by the French Revolution, he crossed to Paris in 1791 to spread the Bible, and back home he published the Cylchgrawn Cynmraeg, one of the first Welsh-language magazines, calling for freedom of religion and the end of the slave trade.",
    "In 1794 he sailed to America. He rode thousands of miles through the young republic, preaching against slavery, and bought land in the Allegheny mountains of Pennsylvania for a Welsh settlement, Cambria, with its town of Beulah. Cambria County, Pennsylvania, still carries the name."],
   ["Ganed Morgan John Rhys ger Llanbradach a daeth yn weinidog gyda’r Bedyddwyr. Wedi’i danio gan y Chwyldro Ffrengig, croesodd i Baris yn 1791 i ledaenu’r Beibl, ac adref cyhoeddodd y Cylchgrawn Cynmraeg, un o’r cylchgronau Cymraeg cyntaf, yn galw am ryddid crefydd a diwedd ar y fasnach gaethweision.",
    "Yn 1794 hwyliodd i America. Marchogodd filoedd o filltiroedd drwy’r weriniaeth ifanc yn pregethu yn erbyn caethwasiaeth, a phrynodd dir ym mynyddoedd Allegheny ym Mhensylfania ar gyfer gwladfa Gymreig, Cambria, a’i thref Beulah. Mae Sir Cambria, Pensylfania, yn dwyn yr enw o hyd."]),
 P("christmas-evans", "industrial", "1766–1838", "Christmas Evans", "Christmas Evans", "The one-eyed preacher", "Y pregethwr un llygad", "Christmas_Evans", "faith",
   "A farm boy from Ceredigion who taught himself to read and became one of the greatest preachers Wales has known, famous for the power of his imagination.",
   "Bachgen fferm o Geredigion a ddysgodd ei hun i ddarllen ac a ddaeth yn un o bregethwyr mwyaf Cymru, yn enwog am rym ei ddychymyg.",
   ["Christmas Evans was born on Christmas Day 1766 near Llandysul. His father died when he was young and he grew up working on farms, unable to read until he was seventeen. He lost an eye in a fight, but found his calling as a Baptist preacher.",
    "For more than thirty years he made Anglesey his home and preached across Wales to crowds of thousands in the open air. His sermons painted pictures so vivid that listeners felt they could see the scenes he described, and he was counted among the three great preachers of Wales."],
   ["Ganed Christmas Evans ar ddydd Nadolig 1766 ger Llandysul. Bu farw ei dad pan oedd yn ifanc a thyfodd i fyny yn gweithio ar ffermydd, heb fedru darllen nes ei fod yn ddwy ar bymtheg. Collodd lygad mewn ymladdfa, ond cafodd ei alwedigaeth fel pregethwr gyda’r Bedyddwyr.",
    "Am dros ddeng mlynedd ar hugain gwnaeth Fôn yn gartref iddo a phregethodd ledled Cymru i dyrfaoedd o filoedd yn yr awyr agored. Peintiai ei bregethau ddarluniau mor fyw nes i’w wrandawyr deimlo y gallent weld y golygfeydd, ac fe’i cyfrifid ymhlith tri phregethwr mawr Cymru."]),
 P("john-gibson", "industrial", "1790–1866", "John Gibson", "John Gibson", "Sculptor in Rome", "Cerflunydd yn Rhufain", "John_Gibson_(sculptor)", "art",
   "Born near Conwy, he became the most famous British sculptor of his day, working in Rome for almost fifty years.",
   "Fe’i ganed ger Conwy a daeth yn gerflunydd Prydeinig enwocaf ei ddydd, gan weithio yn Rhufain am bron i hanner can mlynedd.",
   ["John Gibson was born at Gyffin near Conwy, the son of a market gardener, and spoke Welsh as a child. The family moved to Liverpool, where he was apprenticed to a cabinet maker and then to a monumental mason.",
    "In 1817 he went to Rome to study under the great Canova, and he stayed for the rest of his life. His marble gods and heroes made him famous across Europe, and his Tinted Venus, painted in soft colours as the ancient Greeks had done, caused a sensation. He left his works to the Royal Academy."],
   ["Ganed John Gibson yn y Gyffin ger Conwy, yn fab i arddwr marchnad, a siaradai Gymraeg yn blentyn. Symudodd y teulu i Lerpwl, lle bu’n brentis i saer celfi ac yna i saer maen.",
    "Yn 1817 aeth i Rufain i astudio dan y mawr Canova, ac arhosodd yno weddill ei oes. Gwnaeth ei dduwiau a’i arwyr marmor ef yn enwog ar draws Ewrop, a pharodd ei Fenws Liwiedig, wedi’i phaentio mewn lliwiau tyner fel y gwnâi’r hen Roegiaid, gyffro mawr. Gadawodd ei weithiau i’r Academi Frenhinol."]),
 P("thomas-gee", "industrial", "1815–1898", "Thomas Gee", "Thomas Gee", "Publisher of Denbigh", "Cyhoeddwr Dinbych", "Thomas_Gee", "enterprise",
   "Publisher and campaigner from Denbigh whose newspaper Baner ac Amserau Cymru and ten-volume Welsh encyclopaedia, Y Gwyddoniadur, made him the giant of Welsh publishing.",
   "Cyhoeddwr ac ymgyrchydd o Ddinbych y gwnaeth ei bapur newydd Baner ac Amserau Cymru a’i wyddoniadur Cymraeg deg cyfrol, Y Gwyddoniadur, ef yn gawr cyhoeddi Cymru.",
   ["Thomas Gee took over his father’s printing works in Denbigh and turned it into the greatest Welsh publishing house of the century. Between 1854 and 1879 he published Y Gwyddoniadur Cymreig, an encyclopaedia of ten volumes in Welsh, the biggest venture ever made in Welsh publishing.",
    "In 1857 he founded Baner Cymru, which in 1859 became Baner ac Amserau Cymru and became the most powerful Welsh newspaper of its day. Through it he fought for tenant farmers, for religious equality and for education, and he was one of the leading voices of Victorian Wales."],
   ["Cymerodd Thomas Gee waith argraffu ei dad yn Ninbych a’i droi’n dŷ cyhoeddi Cymraeg mwyaf y ganrif. Rhwng 1854 a 1879 cyhoeddodd Y Gwyddoniadur Cymreig, gwyddoniadur deg cyfrol yn Gymraeg, y fenter fwyaf erioed ym myd cyhoeddi Cymraeg.",
    "Yn 1857 sefydlodd Baner Cymru, a ddaeth yn 1859 yn Baner ac Amserau Cymru ac a ddaeth yn bapur newydd Cymraeg mwyaf dylanwadol ei ddydd. Drwyddo ymladdodd dros ffermwyr tenant, dros gydraddoldeb crefyddol ac addysg, ac roedd yn un o leisiau blaenllaw Cymru oes Fictoria."]),

 # ---------- Twentieth-Century Wales ----------
 P("morfydd-owen", "modern", "1891–1918", "Morfydd Llwyn Owen", "Morfydd Llwyn Owen", "Composer and singer", "Cyfansoddwraig a chantores", "Morfydd_Llwyn_Owen", "music",
   "A brilliant composer and singer from Treforest who wrote some of the finest Welsh songs of the century before her death at twenty-six.",
   "Cyfansoddwraig a chantores ddisglair o Drefforest a ysgrifennodd rai o ganeuon Cymraeg gorau’r ganrif cyn ei marw yn chwech ar hugain oed.",
   ["Morfydd Owen grew up in Treforest and studied at Cardiff and then the Royal Academy of Music in London, where she won prize after prize. She was a fine mezzo-soprano and a gifted pianist as well as a composer.",
    "She wrote orchestral works, piano pieces, hymn tunes and songs, among them settings of Welsh poems that singers still treasure. She died in 1918, aged only twenty-six, and is remembered as one of the great talents of Welsh music."],
   ["Magwyd Morfydd Owen yn Nhrefforest ac astudiodd yng Nghaerdydd ac yna yn yr Academi Gerdd Frenhinol yn Llundain, lle enillodd wobr ar ôl gwobr. Roedd yn fezzo-soprano gain ac yn bianydd dawnus yn ogystal â chyfansoddwraig.",
    "Ysgrifennodd weithiau i gerddorfa, darnau piano, emyn-donau a chaneuon, yn eu plith gosodiadau o gerddi Cymraeg a drysorir gan gantorion o hyd. Bu farw yn 1918, yn ddim ond chwech ar hugain oed, ac fe’i cofir fel un o ddoniau mawr cerddoriaeth Cymru."]),
 P("lewis-valentine", "modern", "1893–1986", "Lewis Valentine", "Lewis Valentine", "First president of Plaid Cymru", "Llywydd cyntaf Plaid Cymru", "Lewis_Valentine", "politics",
   "Baptist minister, first president of Plaid Cymru and one of the three who set fire to the bombing school at Penyberth in 1936. He wrote the hymn ‘Gweddi dros Gymru’.",
   "Gweinidog gyda’r Bedyddwyr, llywydd cyntaf Plaid Cymru ac un o’r tri a roes yr ysgol fomio ym Mhenyberth ar dân yn 1936. Ef a ysgrifennodd yr emyn ‘Gweddi dros Gymru’.",
   ["Lewis Valentine was born in Llanddulas and served in the First World War before becoming a Baptist minister. In 1925 he was one of the founders of Plaid Cymru and its first president, and in 1929 its first candidate at a general election.",
    "In 1936, with Saunders Lewis and D. J. Williams, he set fire to the RAF bombing school being built at Penyberth in Llŷn, then gave himself up to the police. The three were jailed and became heroes to Wales. His hymn ‘Dros Gymru’n gwlad, O Dad, dyrchafwn gri’ is sung to this day."],
   ["Ganed Lewis Valentine yn Llanddulas a bu’n gwasanaethu yn y Rhyfel Byd Cyntaf cyn dod yn weinidog gyda’r Bedyddwyr. Yn 1925 roedd yn un o sylfaenwyr Plaid Cymru a’i llywydd cyntaf, ac yn 1929 ei hymgeisydd cyntaf mewn etholiad cyffredinol.",
    "Yn 1936, gyda Saunders Lewis a D. J. Williams, rhoes yr ysgol fomio a oedd yn cael ei chodi ym Mhenyberth yn Llŷn ar dân, ac yna ildio’i hun i’r heddlu. Carcharwyd y tri a daethant yn arwyr i Gymru. Cenir ei emyn ‘Dros Gymru’n gwlad, O Dad, dyrchafwn gri’ hyd heddiw."],
   first=("wales", "The first president of Plaid Cymru", "Llywydd cyntaf Plaid Cymru", 1925)),
 P("tasker-watkins", "modern", "1918–2007", "Sir Tasker Watkins", "Syr Tasker Watkins", "Victoria Cross and judge", "Croes Victoria a barnwr", "Tasker_Watkins", "heroes",
   "Soldier from Nelson who won the Victoria Cross in Normandy in 1944, then rose to be one of Britain’s senior judges and president of the Welsh Rugby Union.",
   "Milwr o Nelson a enillodd Groes Victoria yn Normandi yn 1944, ac a gododd wedyn yn un o uwch farnwyr Prydain ac yn llywydd Undeb Rygbi Cymru.",
   ["Tasker Watkins, from Nelson in the Taff Bargoed valley, was a lieutenant in the Welch Regiment in August 1944 when his company came under heavy fire in the Normandy cornfields. Taking command, he led a bayonet charge, silenced a machine-gun post single-handed and brought his men back to safety. He was awarded the Victoria Cross.",
    "After the war he became a barrister and judge, rising to Lord Justice of Appeal and deputy chief justice. He was president of the Welsh Rugby Union from 1993 to 2004, and his statue stands at the Millennium Stadium in Cardiff."],
   ["Roedd Tasker Watkins, o Nelson yng nghwm Taf Bargoed, yn is-gapten yn y Gatrawd Gymreig ym mis Awst 1944 pan ddaeth ei gwmni dan dân trwm ym meysydd ŷd Normandi. Gan gymryd yr awenau, arweiniodd ruthr â bidogau, tawelodd nyth gynnau peiriant ar ei ben ei hun a dod â’i wŷr yn ôl yn ddiogel. Dyfarnwyd Croes Victoria iddo.",
    "Wedi’r rhyfel daeth yn fargyfreithiwr ac yn farnwr, gan godi’n Arglwydd Ustus Apêl ac yn ddirprwy brif ustus. Bu’n llywydd Undeb Rygbi Cymru o 1993 hyd 2004, ac mae ei gerflun yn sefyll wrth Stadiwm y Mileniwm yng Nghaerdydd."]),

 # ---------- Wales Today ----------
 P("terry-matthews", "today", "b. 1943", "Sir Terry Matthews", "Syr Terry Matthews", "Telecoms pioneer", "Arloeswr telathrebu", "Terry_Matthews", "enterprise",
   "Newport-born engineer who founded the telecoms giants Mitel and Newbridge Networks, became Wales’s first billionaire and built the Celtic Manor, home of the 2010 Ryder Cup.",
   "Peiriannydd o Gasnewydd a sefydlodd y cwmnïau telathrebu mawr Mitel a Newbridge Networks, a ddaeth yn biliwnydd cyntaf Cymru ac a gododd y Celtic Manor, cartref Cwpan Ryder 2010.",
   ["Terry Matthews was born in Newport and studied electronics at Swansea. He moved to Canada, where in 1973 he co-founded Mitel and later Newbridge Networks, two of the most successful technology companies of their time.",
    "He bought the hospital in Newport where he was born and turned it into the Celtic Manor Resort. In 2010 it brought the Ryder Cup to Wales for the first time, and he has backed hundreds of young technology firms in Wales and Canada."],
   ["Ganed Terry Matthews yng Nghasnewydd ac astudiodd electroneg yn Abertawe. Symudodd i Ganada, lle yn 1973 cyd-sefydlodd Mitel ac wedyn Newbridge Networks, dau o gwmnïau technoleg mwyaf llwyddiannus eu cyfnod.",
    "Prynodd yr ysbyty yng Nghasnewydd lle y’i ganed a’i droi’n Westy’r Celtic Manor. Yn 2010 daeth â Chwpan Ryder i Gymru am y tro cyntaf, ac mae wedi cefnogi cannoedd o gwmnïau technoleg ifanc yng Nghymru a Chanada."]),
 P("carwyn-jones", "today", "b. 1967", "Carwyn Jones", "Carwyn Jones", "First Minister 2009–2018", "Prif Weinidog 2009–2018", "Carwyn_Jones", "politics",
   "First Minister of Wales for nine years, who led the campaign that won full law-making powers for the Senedd in the 2011 referendum.",
   "Prif Weinidog Cymru am naw mlynedd, a arweiniodd yr ymgyrch a enillodd bwerau deddfu llawn i’r Senedd yn refferendwm 2011.",
   ["Carwyn Jones grew up in Bridgend, studied law at Aberystwyth and became a barrister. He was elected to the National Assembly in 1999 and became First Minister in 2009.",
    "In 2011 he led the Yes campaign in the referendum that gave the Senedd the power to make laws for Wales in all its fields. Under him the Senedd passed its first full Acts, among them the organ donation opt-out and the Well-being of Future Generations Act."],
   ["Magwyd Carwyn Jones ym Mhen-y-bont ar Ogwr, astudiodd y gyfraith yn Aberystwyth a daeth yn fargyfreithiwr. Fe’i hetholwyd i’r Cynulliad Cenedlaethol yn 1999 a daeth yn Brif Weinidog yn 2009.",
    "Yn 2011 arweiniodd ymgyrch Ie yn y refferendwm a roddodd i’r Senedd y pŵer i wneud deddfau i Gymru yn ei holl feysydd. Dan ei arweiniad pasiodd y Senedd ei Deddfau llawn cyntaf, yn eu plith y ddeddf rhoi organau a Deddf Llesiant Cenedlaethau’r Dyfodol."]),
 P("mark-drakeford", "today", "b. 1954", "Mark Drakeford", "Mark Drakeford", "First Minister 2018–2024", "Prif Weinidog 2018–2024", "Mark_Drakeford", "politics",
   "Carmarthen-born First Minister who led Wales through the Covid-19 pandemic, choosing a careful Welsh path.",
   "Prif Weinidog o Gaerfyrddin a arweiniodd Gymru drwy bandemig Covid-19, gan ddewis llwybr gofalus Cymreig.",
   ["Mark Drakeford was born in Carmarthen, worked as a probation officer and youth justice worker, and became a professor of social policy at Cardiff. He was elected to the Senedd in 2011 and became First Minister in 2018.",
    "When the pandemic struck in 2020, he led Wales on its own course, explaining the rules in calm daily briefings. His government also brought in free school meals for all primary pupils, a basic income pilot for young people leaving care, and the first steps to a larger Senedd."],
   ["Ganed Mark Drakeford yng Nghaerfyrddin, bu’n swyddog prawf ac yn weithiwr cyfiawnder ieuenctid, a daeth yn athro polisi cymdeithasol yng Nghaerdydd. Fe’i hetholwyd i’r Senedd yn 2011 a daeth yn Brif Weinidog yn 2018.",
    "Pan drawodd y pandemig yn 2020, arweiniodd Gymru ar ei llwybr ei hun, gan esbonio’r rheolau mewn sesiynau dyddiol pwyllog. Cyflwynodd ei lywodraeth hefyd brydau ysgol am ddim i bob disgybl cynradd, cynllun incwm sylfaenol i bobl ifanc sy’n gadael gofal, a’r camau cyntaf at Senedd fwy."]),
 P("ruth-jones", "today", "b. 1966", "Ruth Jones", "Ruth Jones", "Writer of Gavin & Stacey", "Awdur Gavin & Stacey", "Ruth_Jones", "stage",
   "Actress and writer from Porthcawl who co-wrote Gavin & Stacey and played Nessa, putting Barry Island on the map of British comedy.",
   "Actores ac awdur o Borthcawl a gyd-ysgrifennodd Gavin & Stacey ac a chwaraeodd Nessa, gan roi Ynys y Barri ar fap comedi Prydain.",
   ["Ruth Jones grew up in Porthcawl and studied drama at Warwick. In 2007, with James Corden, she created Gavin & Stacey, the story of a love affair between Essex and Barry, in which she played the unforgettable Nessa.",
    "The series became one of the best-loved British comedies, and its Christmas special in 2019 was watched by nearly eighteen million people. She has also written bestselling novels and, with her company Tidy Productions, made the series Stella, set in the Valleys."],
   ["Magwyd Ruth Jones ym Mhorthcawl ac astudiodd ddrama yn Warwick. Yn 2007, gyda James Corden, creodd Gavin & Stacey, stori carwriaeth rhwng Essex a’r Barri, lle chwaraeodd y Nessa fythgofiadwy.",
    "Daeth y gyfres yn un o hoff gomedïau Prydain, a gwyliwyd ei rhaglen Nadolig yn 2019 gan bron i ddeunaw miliwn o bobl. Mae hefyd wedi ysgrifennu nofelau poblogaidd ac, â’i chwmni Tidy Productions, wedi creu’r gyfres Stella, a leolwyd yn y Cymoedd."]),
 P("rob-brydon", "today", "b. 1965", "Rob Brydon", "Rob Brydon", "Comedian and actor", "Digrifwr ac actor", "Rob_Brydon", "stage",
   "Comedian and actor from Port Talbot, star of Marion and Geoff and Gavin & Stacey’s Uncle Bryn, and a master of impressions.",
   "Digrifwr ac actor o Bort Talbot, seren Marion and Geoff ac Wncwl Bryn yn Gavin & Stacey, a meistr ar ddynwared.",
   ["Rob Brydon grew up in Baglan, Port Talbot, and started out in Welsh radio and as a voice artist. His series Marion and Geoff (2000), in which he played a hopeful taxi driver talking to a camera, made his name.",
    "He became a household name as Uncle Bryn in Gavin & Stacey and with Steve Coogan in The Trip, where his small man in a box and duelling impressions won fans around the world. He has also hosted Would I Lie to You? for many years."],
   ["Magwyd Rob Brydon ym Maglan, Port Talbot, a dechreuodd ar radio yng Nghymru ac fel artist lleisiol. Gwnaeth ei gyfres Marion and Geoff (2000), lle chwaraeodd yrrwr tacsi gobeithiol yn siarad â chamera, ei enw.",
    "Daeth yn enw cyfarwydd fel Wncwl Bryn yn Gavin & Stacey a gyda Steve Coogan yn The Trip, lle enillodd ei ddyn bach mewn bocs a’i ornestau dynwared ffans ledled y byd. Mae hefyd wedi cyflwyno Would I Lie to You? ers blynyddoedd."]),
 P("gruff-rhys", "today", "b. 1970", "Gruff Rhys", "Gruff Rhys", "Singer of Super Furry Animals", "Canwr y Super Furry Animals", "Gruff_Rhys", "music",
   "Singer of the Super Furry Animals, whose all-Welsh album Mwng (2000) reached the UK top twenty, and a restless, inventive solo artist.",
   "Canwr y Super Furry Animals, y cyrhaeddodd eu halbwm Cymraeg Mwng (2000) ugain uchaf siartiau Prydain, ac artist unigol aflonydd a dyfeisgar.",
   ["Gruff Rhys grew up in Bethesda and sang in Welsh-language bands before forming the Super Furry Animals in Cardiff in the 1990s. Their mix of psychedelic pop, wit and Welsh pride made them one of the most loved bands of the Cool Cymru years.",
    "In 2000 they released Mwng, sung entirely in Welsh, which reached the UK top twenty, a landmark for the language. As a solo artist he has made albums, films and the travelling show American Interior, about the Welsh explorer John Evans of Waunfawr."],
   ["Magwyd Gruff Rhys ym Methesda a chanodd mewn bandiau Cymraeg cyn ffurfio’r Super Furry Animals yng Nghaerdydd yn y 1990au. Gwnaeth eu cymysgedd o bop seicedelig, ffraethineb a balchder Cymreig hwy yn un o fandiau anwylaf blynyddoedd Cŵl Cymru.",
    "Yn 2000 rhyddhawyd Mwng, wedi’i chanu’n gyfan gwbl yn Gymraeg, a gyrhaeddodd ugain uchaf siartiau Prydain, carreg filltir i’r iaith. Fel artist unigol mae wedi creu albymau, ffilmiau a’r sioe deithiol American Interior, am y fforiwr o Gymro John Evans o’r Waunfawr."]),
 P("sam-warburton", "today", "b. 1988", "Sam Warburton", "Sam Warburton", "Captain of Wales and the Lions", "Capten Cymru a’r Llewod", "Sam_Warburton", "sport",
   "Cardiff flanker who captained Wales at 22 and led the British and Irish Lions on two tours, winning the series in Australia in 2013.",
   "Blaenasgellwr o Gaerdydd a fu’n gapten Cymru yn ddwy ar hugain ac a arweiniodd y Llewod Prydeinig a Gwyddelig ar ddwy daith, gan ennill y gyfres yn Awstralia yn 2013.",
   ["Sam Warburton grew up in Rhiwbina, Cardiff, and played for Cardiff Blues. In 2011 he was made Wales captain at just 22 and led his country to the semi-final of the World Cup in New Zealand, and in 2012 to a Grand Slam.",
    "In 2013 he captained the British and Irish Lions to a series win in Australia, their first series victory for sixteen years, and in 2017 he led them again to a drawn series against the All Blacks in New Zealand. He captained Wales 49 times."],
   ["Magwyd Sam Warburton yn Rhiwbeina, Caerdydd, a chwaraeodd i Gleision Caerdydd. Yn 2011 fe’i gwnaed yn gapten Cymru yn ddim ond dwy ar hugain ac arweiniodd ei wlad i rownd gynderfynol Cwpan y Byd yn Seland Newydd, ac yn 2012 i Gamp Lawn.",
    "Yn 2013 bu’n gapten ar y Llewod Prydeinig a Gwyddelig i fuddugoliaeth yn y gyfres yn Awstralia, eu buddugoliaeth gyntaf mewn cyfres ers un mlynedd ar bymtheg, ac yn 2017 arweiniodd hwy eto i gyfres gyfartal yn erbyn y Crysau Duon yn Seland Newydd. Bu’n gapten Cymru 49 o weithiau."]),
]
